import { GuestRegistry } from "./guestRegistry.ts";
import type { TailnetPacketPort } from "./tailscaleNode";

const ETH_IPV4 = 0x0800;
const ETH_ARP = 0x0806;

export function macToBytes(mac: string): Uint8Array {
  const parts = mac.split(":").map((part) => Number.parseInt(part, 16));
  if (parts.length !== 6 || parts.some((part) => !Number.isInteger(part) || part < 0 || part > 255)) {
    throw new TypeError(`invalid MAC: ${mac}`);
  }
  return Uint8Array.from(parts);
}

function macString(bytes: Uint8Array): string {
  return [...bytes].map((part) => part.toString(16).padStart(2, "0")).join(":");
}

function ipBytes(ip: string): Uint8Array { return Uint8Array.from(ip.split(".").map(Number)); }
function ipString(bytes: Uint8Array): string { return [...bytes].join("."); }
function same(a: Uint8Array, b: Uint8Array): boolean { return a.length === b.length && a.every((v, i) => v === b[i]); }

export class RouterGateway {
  readonly #gatewayIP: Uint8Array;
  readonly #gatewayMAC: Uint8Array;
  readonly #registry: GuestRegistry;
  readonly #packetPort: TailnetPacketPort;
  readonly #sendFrame: (frame: Uint8Array) => void;
  readonly #infra: { ip: string; mac: string } | null;

  constructor(options: {
    gatewayIp: string;
    gatewayMac: string;
    registry: GuestRegistry;
    packetPort: TailnetPacketPort;
    sendFrame(frame: Uint8Array): void;
    infra?: { ip: string; mac: string };
  }) {
    this.#gatewayIP = ipBytes(options.gatewayIp);
    this.#gatewayMAC = macToBytes(options.gatewayMac);
    this.#registry = options.registry;
    this.#packetPort = options.packetPort;
    this.#sendFrame = options.sendFrame;
    this.#infra = options.infra ? { ip: options.infra.ip, mac: options.infra.mac.toLowerCase() } : null;
  }

  ingestFrame(frame: Uint8Array): boolean {
    if (frame.length < 14) return false;
    const type = (frame[12] << 8) | frame[13];
    if (type === ETH_ARP) return this.#arp(frame);
    if (type !== ETH_IPV4 || !same(frame.subarray(0, 6), this.#gatewayMAC)) return false;
    const packetLength = (frame[16] << 8) | frame[17];
    const packet = frame.subarray(14, 14 + packetLength);
    if (!validIPv4(packet)) return false;
    const sourceIP = ipString(packet.subarray(12, 16));
    const registration = this.#registry.resolveByIP(sourceIP);
    const sourceMAC = macString(frame.subarray(6, 12));
    const infraOK = this.#infra?.ip === sourceIP && this.#infra.mac === sourceMAC;
    if ((!registration || registration.mac !== sourceMAC) && !infraOK) return false;
    return this.#packetPort.write(Uint8Array.from(packet));
  }

  ingestPacket(packet: Uint8Array): boolean {
    if (!validIPv4(packet)) return false;
    const destinationIP = ipString(packet.subarray(16, 20));
    const destination = this.#registry.resolveByIP(destinationIP);
    const destinationMAC = destination?.mac ?? (this.#infra?.ip === destinationIP ? this.#infra.mac : null);
    if (!destinationMAC) return false;
    const frame = new Uint8Array(14 + packet.length);
    frame.set(macToBytes(destinationMAC), 0);
    frame.set(this.#gatewayMAC, 6);
    frame[12] = 0x08; frame[13] = 0x00;
    frame.set(packet, 14);
    this.#sendFrame(frame);
    return true;
  }

  #arp(frame: Uint8Array): boolean {
    if (frame.length < 42) return false;
    const arp = frame.subarray(14);
    const operation = (arp[6] << 8) | arp[7];
    if (operation !== 1 || !same(arp.subarray(24, 28), this.#gatewayIP)) return false;
    const reply = new Uint8Array(42);
    reply.set(frame.subarray(6, 12), 0);
    reply.set(this.#gatewayMAC, 6);
    reply.set([0x08, 0x06, 0, 1, 0x08, 0, 6, 4, 0, 2], 12);
    reply.set(this.#gatewayMAC, 22);
    reply.set(this.#gatewayIP, 28);
    reply.set(arp.subarray(8, 14), 32);
    reply.set(arp.subarray(14, 18), 38);
    this.#sendFrame(reply);
    return true;
  }
}

export async function attachRouterGateway(options: {
  hubUrl: string;
  gatewayIp: string;
  gatewayMac: string;
  registry: GuestRegistry;
    handle: { packetPort(onPacket: (packet: Uint8Array) => void): TailnetPacketPort | null };
  infra?: { ip: string; mac: string };
}): Promise<{ close(): void }> {
  const socket = new WebSocket(options.hubUrl);
  socket.binaryType = "arraybuffer";
  await new Promise<void>((resolve, reject) => {
    socket.onopen = () => resolve();
    socket.onerror = () => reject(new Error(`router gateway cannot connect to ${options.hubUrl}`));
  });
  let gateway: RouterGateway | null = null;
  const port = options.handle.packetPort((packet) => gateway?.ingestPacket(packet));
  if (!port) { socket.close(); throw new Error("Tailscale WASM packetPort is unavailable or already open"); }
  gateway = new RouterGateway({
    gatewayIp: options.gatewayIp,
    gatewayMac: options.gatewayMac,
    registry: options.registry,
    packetPort: port,
    sendFrame: (frame) => { if (socket.readyState === WebSocket.OPEN) socket.send(frame); },
    infra: options.infra,
  });
  socket.onmessage = (event) => {
    if (event.data instanceof ArrayBuffer) gateway?.ingestFrame(new Uint8Array(event.data));
  };
  return { close() { port.close(); socket.close(); gateway = null; } };
}

function validIPv4(packet: Uint8Array): boolean {
  if (packet.length < 20 || packet[0] >>> 4 !== 4) return false;
  const headerLength = (packet[0] & 0x0f) * 4;
  const totalLength = (packet[2] << 8) | packet[3];
  return headerLength >= 20 && totalLength >= headerLength && totalLength <= packet.length;
}

export interface GuestRegistration {
  guestId: string;
  hostname: string;
  ip: string;
  mac: string;
  sessionId: string;
}

interface StoredRegistration extends GuestRegistration { seenAt: number }

export class GuestRegistry {
  readonly #byGuest = new Map<string, StoredRegistration>();
  readonly #byIP = new Map<string, StoredRegistration>();
  readonly #byMAC = new Map<string, StoredRegistration>();
  readonly #now: () => number;
  readonly #ttlMs: number;
  readonly #maxEntries: number;

  constructor(options: { now?: () => number; ttlMs?: number; maxEntries?: number } = {}) {
    this.#now = options.now ?? Date.now;
    this.#ttlMs = options.ttlMs ?? 15_000;
    this.#maxEntries = options.maxEntries ?? 128;
  }

  register(value: GuestRegistration): boolean {
    const key = this.#key(value.guestId, value.sessionId);
    const previous = this.#byGuest.get(key);
    const ipOwner = this.#byIP.get(value.ip);
    const mac = value.mac.toLowerCase();
    const macOwner = this.#byMAC.get(mac);
    if ((ipOwner && ipOwner !== previous) || (macOwner && macOwner !== previous)) return false;
    if (!previous && this.#byGuest.size >= this.#maxEntries) return false;
    if (previous) this.#drop(previous);
    const stored = { ...value, mac, seenAt: this.#now() };
    this.#byGuest.set(key, stored);
    this.#byIP.set(stored.ip, stored);
    this.#byMAC.set(stored.mac, stored);
    return true;
  }

  heartbeat(guestId: string, sessionId: string): boolean {
    const found = this.#byGuest.get(this.#key(guestId, sessionId));
    if (!found) return false;
    found.seenAt = this.#now();
    return true;
  }

  remove(guestId: string, sessionId: string): boolean {
    const found = this.#byGuest.get(this.#key(guestId, sessionId));
    if (!found) return false;
    this.#drop(found);
    return true;
  }

  resolveByIP(ip: string): GuestRegistration | null {
    const value = this.#byIP.get(ip);
    return value ? this.#public(value) : null;
  }

  validateSource(ip: string, mac: string, sessionId: string): boolean {
    const value = this.#byIP.get(ip);
    return !!value && value.mac === mac.toLowerCase() && value.sessionId === sessionId;
  }

  expire(): number {
    let count = 0;
    const cutoff = this.#now() - this.#ttlMs;
    for (const value of [...this.#byGuest.values()]) {
      if (value.seenAt < cutoff) { this.#drop(value); count++; }
    }
    return count;
  }

  #key(guestId: string, sessionId: string): string { return `${sessionId}\0${guestId}`; }
  #drop(value: StoredRegistration): void {
    this.#byGuest.delete(this.#key(value.guestId, value.sessionId));
    if (this.#byIP.get(value.ip) === value) this.#byIP.delete(value.ip);
    if (this.#byMAC.get(value.mac) === value) this.#byMAC.delete(value.mac);
  }
  #public(value: StoredRegistration): GuestRegistration {
    const { seenAt: _seenAt, ...registration } = value;
    return registration;
  }
}

