    #!/usr/bin/env node
    import assert from "node:assert/strict";
    import { GuestRegistry } from "../src/net/guestRegistry.ts";
    import { RouterGateway, macToBytes } from "../src/net/routerGateway.ts";

    function ipv4(src, dst, proto = 17) {
      const p = new Uint8Array(20);
      p[0] = 0x45;
      p[2] = 0;
      p[3] = 20;
      p[8] = 64;
      p[9] = proto;
      p.set(src.split(".").map(Number), 12);
      p.set(dst.split(".").map(Number), 16);
      return p;
    }

    function ethernet(dst, src, type, payload) {
      const f = new Uint8Array(14 + payload.length);
      f.set(macToBytes(dst), 0);
      f.set(macToBytes(src), 6);
      f[12] = type >>> 8;
      f[13] = type & 255;
      f.set(payload, 14);
      return f;
    }

    // ── 1. Subnet membership check in ingestFrame ──
    const registry = new GuestRegistry();
    const foreignIp = "192.168.99.5";
    const foreignMac = "02:00:00:00:00:99";
    registry.register({
      guestId: "foreign-guest",
      hostname: "foreign.local",
      ip: foreignIp,
      mac: foreignMac,
      sessionId: "tab-foreign",
    });

    const writes = [];
    const frames = [];
    const gateway = new RouterGateway({
      subnetCidr: "10.86.210.0/24",
      gatewayIp: "10.86.210.1",
      gatewayMac: "02:86:00:00:00:01",
      registry,
      packetPort: {
        write: (packet) => {
          writes.push(Uint8Array.from(packet));
          return true;
        },
        close() {},
      },
      sendFrame: (frame) => frames.push(Uint8Array.from(frame)),
    });

    const outboundPacket = ipv4(foreignIp, "100.92.105.1", 17);
    const outboundFrame = ethernet("02:86:00:00:00:01", foreignMac, 0x0800, outboundPacket);

    // ingestFrame should reject packets whose source IP is not in subnetCidr
    const accepted = gateway.ingestFrame(outboundFrame);
    assert.equal(
      accepted,
      false,
      `Frame with source IP ${foreignIp} outside router subnet 10.86.210.0/24 must be rejected`
    );
    assert.equal(
      writes.length,
      0,
      "packetPort.write must not be called for frame outside subnet"
    );

    // Also verify legitimate packet in subnet is accepted
    const legitimateIp = "10.86.210.33";
