  const octets = match.slice(1, 5).map(Number);
  const prefixLength = Number(match[5]);
  if (octets.some((part) => !Number.isInteger(part) || part < 0 || part > 255)) return null;
  const [a, b, slot, host] = octets;
  if (a !== ROUTER_POOL_A || b !== ROUTER_POOL_B || prefixLength !== 24) return null;
  if (slot < FIRST_SLOT || slot > LAST_SLOT || host !== 0) return null;
  return { cidr: `${a}.${b}.${slot}.0/24`, prefix: `${a}.${b}.${slot}`, slot };
}

export function addressPlan(cidr) {
  const subnet = parseRouterSubnet(cidr);
  if (!subnet) throw new TypeError(`invalid router subnet: ${cidr}`);
  return {
    cidr: subnet.cidr,
    prefix: subnet.prefix,
    network: `${subnet.prefix}.0`,
    gateway: `${subnet.prefix}.1`,
    dns: `${subnet.prefix}.2`,
    guestFirst: 33,
    guestLast: 99,
    serverFirst: 250,
  };
}

export function routerSubnetCandidates(hostname) {
  const start = fnv1a(String(hostname)) % LAST_SLOT;
  return Array.from({ length: LAST_SLOT }, (_, index) =>
    `10.86.${FIRST_SLOT + ((start + index) % LAST_SLOT)}.0/24`);
}

export function selectRouterSubnet({ override, persisted, hostname, occupied = new Set() }) {
  const used = occupied instanceof Set ? occupied : new Set(occupied);
  if (override !== undefined && override !== null && override !== "") {
    const parsed = parseRouterSubnet(override);
    if (!parsed) throw new TypeError(`invalid router subnet override: ${override}`);
    if (used.has(parsed.cidr)) throw new Error(`router subnet is occupied: ${parsed.cidr}`);
    return { cidr: parsed.cidr, source: "override" };

