/**
 * V86Instance — v86 实例封装 + HybridNetworkAdapter 挂载
 *
 * 网络接入方式（零侵入 v86），二选一：
 *
 * 【默认 hybrid 模式】
 * - 不传 relay_url，v86 不创建任何内置 adapter，但 NE2K 网卡仍存在
 * - 通过 emulator.add_listener("net0-send", ...) 拦截 VM 发出的帧
 * - 通过 emulator.bus.send("net0-receive", ...) 向 VM 注入帧
 * - 手动创建 FetchNetworkAdapter 处理外网（DHCP/ARP/DNS/TCP）
 * - BroadcastChannelTransport 处理内网（跨 Tab 以太网广播）
 *
 * 【LAN 模式】（config.lanRelayUrl 非空时）
 * - 走 v86 官方后端：net_device: { type: "virtio", relay_url }
 *   （starter.js 据此创建 NetworkAdapter + virtio-net，见 src/browser/network.js）
 * - relay_url 指向 ws-relay-hub（经 vite 的 /__ws/net 同源代理），即一个 L2 广播 hub；
 *   跨 tab、跨浏览器、甚至和 Node 侧 two-node-lan.mjs 起的实例都在同一根"虚拟网线"上
 * - **自带 DHCP**：本实例会在页面里起一个只服务自家 guest 的 DHCP 服务端
 *   （src/net/dhcpServer.mjs），地址由 tab 名确定性哈希得到（src/net/guestAddress.mjs）。
 *   guest 侧 `init` 里本来就在跑的 `udhcpc` 于是拿得到租约 —— guest 镜像零改动。
 *   手工配静态 IP 的老路子仍然管用（NetworkPanel），只是不再是必须的。
 * - 此模式下不建 FetchNetworkAdapter / BroadcastChannel —— 帧全部由官方 adapter 收发
 */

// @ts-ignore — v86 plain JS, no bundled types
import { FetchNetworkAdapter } from "v86-src/browser/fetch_network.js";

import { BroadcastChannelTransport } from "@/network/transport/BroadcastChannelTransport";
import { DhcpServer } from "@/net/dhcpServer.mjs";
import { MdnsResponder } from "@/net/mdnsResponder.mjs";
import { setGuestLease } from "@/net/guestLease";
import { LEGACY_ADDRESS_PLAN, tabName } from "@/net/guestAddress.mjs";
import { addressPlan } from "@/net/routerSubnet.mjs";
import { resolveRouterSubnet } from "@/net/routerSubnetStore";
import { guestSessionId, publishGuestRegistration } from "@/net/guestRegistryBus";
import {
  getDstMac,
  getSrcMac,
  isBroadcast,
  macEquals,
  macToString,
  stringToMac,
} from "@/network/eth-utils";
import type { HybridNetworkAdapterConfig, NetworkState } from "@/network/HybridNetworkAdapter";

declare global {
  interface Window {
    V86: new (config: V86Config) => V86EmulatorInstance;
  }
}

interface V86Config {
  /** 关掉 v86 自带的 getUserMedia 采集;宿主自己推 adc-push-data。
   *  初值走这里,运行时改走 bus.send("mic-internal-enable", boolean)。 */
  disable_internal_mic?: boolean;
  wasm_path: string;
  memory_size: number;
  vga_memory_size: number;
  screen_container?: HTMLElement;
  bios: { url: string };
  vga_bios: { url: string };
  bzimage?: { url: string };
  initrd?: { url: string };
  cdrom?: { url: string };
  autostart: boolean;
  disable_keyboard?: boolean;
  disable_mouse?: boolean;
  cmdline?: string;
  bzimage_initrd_from_filesystem?: boolean;
  /** 9p 共享盘(virtio-9p)。启动期配置:不给这个字段,emulator.fs9p /
   *  create_file 都不存在。guest init 把它 mount 在 /mnt 并软链 /share;
   *  kws 模型(kws/)与录音持久化(recordings/,@/audio/recordingsStore)
   *  都在这块盘上。空对象 = 空盘,文件由宿主侧开机后灌入。 */
  filesystem?: object;
  // hybrid 模式下**不要**设置 net_device / relay_url（我们手动挂 adapter）；
  // LAN 模式下设置官方 virtio + relay_url 后端。
  net_device?: { type: "virtio"; relay_url: string };
}

interface V86Bus {
  send(event: string, data: unknown): void;
  register(event: string, cb: (...args: unknown[]) => void, thisArg?: unknown): void;
}

interface V86EmulatorInstance {
  destroy(): void;
  serial0_send(char: string): void;
  add_listener(event: string, cb: (...args: unknown[]) => void): void;
  bus: V86Bus;
  /**
   * v86's SpeakerAdapter (starter.js:322, created unless `disable_speaker`).
   * Reached by @/audio/downsampler to borrow `speaker_adapter.mic.downsample_buffer`
   * — v86's Kaiser-window sinc resampler — instead of the app keeping its own.
   * Shape stays `unknown` here; the narrowing lives in one place, downsampler.ts.
   */
  speaker_adapter?: unknown;
  /**
   * v86's NetworkAdapter (starter.js:269, only in LAN mode — created when
   * net_device.relay_url is a plain ws(s):// URL). `socket` is the raw
   * WebSocket to the relay; its readyState is the LAN link state shown in
   * NetworkPanel. The adapter auto-reconnects every 10s on close.
   */
  network_adapter?: { socket?: { readyState: number }; url?: string };
}

/** LAN 链路状态 —— NetworkPanel 轮询用 */
export type LanLinkState = "off" | "connecting" | "online" | "offline";

export interface V86InstanceConfig {
  screenContainer?: HTMLElement;
  wasmPath?: string;
  biosUrl?: string;
  vgaBiosUrl?: string;
  bzimageUrl?: string;
  initrdUrl?: string;
  cdromUrl?: string;
  cmdline?: string;
  memorySize?: number;
  vgaMemorySize?: number;
  networkConfig?: HybridNetworkAdapterConfig;
  /**
   * 非空 → LAN 模式：用官方 virtio + relay_url 后端连 ws-relay-hub。
   * 空 → 默认 hybrid 模式（FetchNetworkAdapter + BroadcastChannel）。
   * 只在 start() 时生效 —— v86 的 net_device 是启动期配置，改它要重启 VM。
   */
  lanRelayUrl?: string;
}

export class V86Instance {
  private emulator: V86EmulatorInstance | null = null;
  private fetchAdapter: unknown = null;
  private transport: BroadcastChannelTransport | null = null;
  private dhcp: DhcpServer | null = null;
  private mdns: MdnsResponder | null = null;
  /**
   * Health of the default-on mDNS/DNS responder, for NetworkPanel to render
   * truthfully (finding #5). "off" before it starts, "up" while it can answer,
   * "down" once its member died post-open. getMdnsHealth() is the read path.
   */
  private mdnsHealth: "off" | "up" | "down" = "off";
  private mdnsHealthTimer: ReturnType<typeof setInterval> | null = null;
  private stopGuestRegistration: (() => void) | null = null;
  private lanMode = false;
  private _networkState: NetworkState | null = null;
  private stateListeners: Array<(state: NetworkState) => void> = [];

  start(config: V86InstanceConfig): void {
    if (!window.V86) {
      throw new Error("V86 not loaded. Ensure libv86.js is included before main.tsx.");
    }

    const netCfg = config.networkConfig || {};
    const routerMacStr = netCfg.routerMac || "52:54:00:01:02:03";
    const routerMac = stringToMac(routerMacStr);
    const routerIp = netCfg.routerIp || "192.168.86.1";

    // Pick a random IP in 192.168.86.100-199 for this VM
    // (full IP negotiation can be layered on top later)
    const vmIpSuffix = 100 + Math.floor(Math.random() * 100);
    const vmIp = `192.168.86.${vmIpSuffix}`;

    const lanUrl = config.lanRelayUrl || null;
    this.lanMode = !!lanUrl;

    // hybrid 模式才需要 BroadcastChannel LAN transport;
    // LAN 模式帧全部走官方 NetworkAdapter,不建它。
    const transport = lanUrl ? null : new BroadcastChannelTransport("0");
    this.transport = transport;

    // Track VM MAC learned from first outgoing frame
    let vmMac: Uint8Array | null = null;

    const updateState = (partial: Partial<NetworkState>) => {
      this._networkState = {
        vmIp,
        vmMac: null,
        routerIp,
        routerMac: routerMacStr,
        peers: [],
        ready: false,
        ...this._networkState,
        ...partial,
      };
      for (const cb of this.stateListeners) cb(this._networkState!);
    };

    if (!lanUrl) updateState({ vmIp, ready: false });

    // Build v86 config — deliberately no relay_url so v86 creates no adapter
    const v86Config: V86Config = {
      // v86 内部麦克风默认关闭:本 app 自己管麦克风(toggleMic)。
      // 运行时切换走 bus.send("mic-internal-enable", …)。
      disable_internal_mic: true,
      wasm_path: config.wasmPath || "/v86/v86.wasm",
      memory_size: config.memorySize || 64 * 1024 * 1024,
      vga_memory_size: config.vgaMemorySize || 2 * 1024 * 1024,
      bios: { url: config.biosUrl || "/bios/seabios.bin" },
      vga_bios: { url: config.vgaBiosUrl || "/bios/vgabios.bin" },
      // 9p 共享盘常开:录音持久化要在录完时随时可写(guest /share/recordings),
      // 空盘的代价只是一个闲置的 virtio-9p 设备(tests/audiod-kws-loop.mjs
      // 同配置已实证不影响既有音频/网络路径)。
      filesystem: {},
      autostart: true,
    };

    if (config.bzimageUrl) v86Config.bzimage = { url: config.bzimageUrl };
    if (config.initrdUrl) v86Config.initrd = { url: config.initrdUrl };
    if (config.cdromUrl) v86Config.cdrom = { url: config.cdromUrl };
    if (config.cmdline) v86Config.cmdline = config.cmdline;
    if (config.screenContainer) v86Config.screen_container = config.screenContainer;
    // LAN 模式:官方 virtio-net + relay WebSocket 后端(零 v86 补丁)
    if (lanUrl) v86Config.net_device = { type: "virtio", relay_url: lanUrl };

    this.emulator = new window.V86(v86Config);
    const emulator = this.emulator;

    // Debug/diagnostic handle, same family as v86's own __sb16 / __audioCtx.
    // Lets in-page test cases and the console reach speaker_adapter.mic without
    // an app instance in hand.
    (window as unknown as { __v86Emulator?: unknown }).__v86Emulator = emulator;

    /**
     * 本标签页里 v86 被**创建**过几次。
     *
     * "面板开合不许重启 VM"这条硬指标需要一个可观测量来证伪 —— 光看"没报错"
     * 证明不了任何事,`__v86Emulator` 的对象身份也只在同一次 evaluate 里可比。
     * 这个计数器是唯一在 `new V86(...)` 那一行自增的地方:**开合面板一百次,
     * 它必须一次不涨**(tests/test-lab-panel.mjs 断言的就是它 + guest uptime)。
     */
    const w = window as unknown as { __v86StartCount?: number };
    w.__v86StartCount = (w.__v86StartCount ?? 0) + 1;

    if (lanUrl) {
      // LAN 模式:官方 NetworkAdapter 已由 v86 自己创建并连 relay,
      // 这里不再挂任何手动 adapter/listener —— 只把自家的 DHCP 服务端拉起来。
      this.startDhcp(lanUrl);
      return;
    }

    // Create FetchNetworkAdapter manually and attach to v86's bus.
    // FetchNetworkAdapter registers its own "net0-send" listener internally.
    this.fetchAdapter = new FetchNetworkAdapter(emulator.bus, {
      router_mac: routerMacStr,
      router_ip: routerIp,
      vm_ip: vmIp,
      dns_method: netCfg.dnsMethod || "doh",
      doh_server: netCfg.dohServer,
      cors_proxy: netCfg.corsProxy,
    });

    // Intercept outgoing frames: add our LAN routing on top of fetch adapter.
    // FetchNetworkAdapter already listens on "net0-send"; we add a second listener
    // for LAN broadcast/unicast forwarding.
    emulator.add_listener("net0-send", (...args: unknown[]) => {
      const frame = args[0] as Uint8Array;
      if (frame.length < 14) return;

      // Learn VM MAC from first outgoing frame
      if (!vmMac) {
        vmMac = getSrcMac(frame);
        updateState({ vmMac: macToString(vmMac), ready: true });
      }

      const dst = getDstMac(frame);

      if (isBroadcast(dst)) {
        // Broadcast: FetchNetworkAdapter already handles WAN side.
        // Also send to LAN so other VM tabs receive it.
        transport!.send(frame);
      } else if (macEquals(dst, routerMac)) {
        // Unicast to gateway: FetchNetworkAdapter handles it. Nothing for LAN.
      } else {
        // Unicast to peer VM: LAN only (FetchNetworkAdapter won't know this MAC)
        transport!.send(frame);
      }
    });

    // Frames from other VM tabs → inject into this VM
    transport!.onReceive((frame: Uint8Array) => {
      emulator.bus.send("net0-receive", frame);
    });
  }

  /** 当前实例是否以 LAN 模式(virtio + relay)启动 */
  isLanMode(): boolean {
    return this.lanMode;
  }

  /**
   * LAN 链路状态。off = 非 LAN 模式;connecting/online/offline 直接映射
   * relay WebSocket 的 readyState(adapter 断线后每 10s 自动重连)。
   */
  getLanLink(): LanLinkState {
    if (!this.lanMode || !this.emulator) return "off";
    const sock = this.emulator.network_adapter?.socket;
    if (!sock) return "connecting";
    if (sock.readyState === 1) return "online";
    if (sock.readyState === 0) return "connecting";
    return "offline";
  }

  getEmulator(): V86EmulatorInstance | null {
    return this.emulator;
  }

  getBus(): V86Bus | null {
    return this.emulator?.bus ?? null;
  }

  serial0Send(data: string): void {
    if (!this.emulator) return;
    for (const ch of data) {
      this.emulator.serial0_send(ch);
    }
  }

  onSerial0Output(cb: (char: string) => void): () => void {
    if (!this.emulator) return () => {};
    // v86 fires serial0-output-byte with a numeric byte value
    this.emulator.add_listener("serial0-output-byte", (...args: unknown[]) => {
      cb(String.fromCharCode(args[0] as number));
    });
    return () => {};
  }

  /**
   * 起这个 tab 自己的 DHCP 服务端(只在 LAN 模式下)。
   *
   * ## 为什么要等、等的是什么
   * guest 的 MAC 是 v86 在 `VirtioNet` 构造函数里**随机**生成的
   * (`00:22:15:xx:xx:xx`,见 vendor/v86/src/virtio_net.js),没有配置项可以指定,
   * 只能读出来。而 `v86.cpu` 要等 wasm 加载完才存在 —— 实测开机后约 0.5s 可读。
   * 所以这里轮询,不是拍脑袋 sleep。
   *
   * ## 时间预算(这是硬的)
   * guest 的 `udhcpc` 用的是 busybox 默认 `-t 3 -T 3`,约 **9 秒**就彻底放弃,
   * 而且 `init` 里带了 `-n`(拿不到就退出)——**它不会再试第二轮**。
   * 幸好从开机到 `init:19` 要十几秒,而 MAC 0.5s 就位,所以选址(ARP 探测)
   * 完全来得及在 guest 开口之前跑完。**别把这段挪到开机之后。**
   *
   * 失败一律只记日志:DHCP 起不来最多是回到"没有地址"的老状态
   * (手工 `ip addr add` 仍然管用),绝不能连累 VM 开机。
   */
  private startDhcp(lanUrl: string): void {
    const deadline = Date.now() + 15_000;
    const poll = async () => {
      const emu = this.emulator as unknown as {
        v86?: { cpu?: { devices?: { virtio_net?: { mac?: Uint8Array } } } };
      } | null;
      const mac = emu?.v86?.cpu?.devices?.virtio_net?.mac;
      if (!mac) {
        if (Date.now() < deadline && this.emulator) setTimeout(poll, 100);
        else console.warn("[dhcp] 读不到 guest 网卡 MAC,DHCP 服务端没起 —— guest 会没有地址");
        return;
      }
      try {
        const name = tabName();
        let plan = LEGACY_ADDRESS_PLAN;
        try {
          const resolved = resolveRouterSubnet({ self: { name }, peers: [] }, { hostname: name });
          if (resolved.kind === "ready") {
            plan = addressPlan(resolved.cidr);
          }
        } catch (e) {
          console.warn("[dhcp] resolveRouterSubnet 失败，降级到 LEGACY_ADDRESS_PLAN:", e);
        }
        // Construct with option 6 WITHHELD (dns:null). Finding #5 option A,
        // safer-of-two choice: never hand even the first lease a nameserver
        // whose health is not yet confirmed. watchMdnsHealth() advertises
        // INFRA_MEMBER_IP once the responder's attach() resolves (confirmed
        // healthy), and withdraws it again if the responder dies post-open.
        const server = new DhcpServer({
          hubUrl: lanUrl,
          guestMac: mac,
          name,
          plan,
          router: plan.gateway,
          dns: null,
        });
        this.dhcp = server;
        // 诊断口子:测试与控制台据此自证"地址是怎么来的",不必去猜。
        (window as unknown as { __v86Dhcp?: unknown }).__v86Dhcp = server;
        // Name discovery rides along wherever the DHCP server starts
        // (default-on): in-page mDNS responder + unicast DNS on :53
        // (src/net/mdnsResponder.mjs). Failure only logs — missing name
        // resolution must never break boot, same policy as DHCP itself.
        const responder = new MdnsResponder({ hubUrl: lanUrl, ip: plan.dns, gateway: plan.gateway });
        this.mdns = responder;
        (window as unknown as { __v86Mdns?: unknown }).__v86Mdns = responder;
        const MDNS_ATTACH_TIMEOUT_MS = 2000;
        const timeoutPromise = new Promise<void>((resolve) => {
          setTimeout(() => {
            console.warn(`[mdns] responder attach 超时 (${MDNS_ATTACH_TIMEOUT_MS}ms),降级先启动 DHCP`);
            if (this.mdns === responder && this.mdnsHealth === "off") {
              this.mdnsHealth = "down";
            }
            resolve();
          }, MDNS_ATTACH_TIMEOUT_MS);
        });
        const attachPromise = responder
          .attach()
          .then(() => {
            this.watchMdnsHealth(responder, server, name);
          })
          .catch((e) => {
            // DNS failure degrades to a lease without option 6; it never blocks boot.
            console.warn("[mdns] responder 起不来(open 前就失败):", e);
            if (this.mdns === responder) this.mdnsHealth = "down";
          });
        await Promise.race([attachPromise, timeoutPromise]);
        const ip = await server.attach();
        // Liveness guard — same shape as the MAC-poll branch above (the
        // `this.emulator` check): attach() awaits ARP address selection, during
        // which destroy() may have torn this instance down (this.dhcp -> null)
        // or a restart replaced it. Publishing a lease for a server that is no
        // longer ours resurrects a zombie address in the guestLease store.
        if (this.dhcp !== server) {
          server.detach();
          responder.detach();
          console.warn(`[dhcp] tab "${name}" 选址完成时实例已销毁/替换,丢弃陈租约 ${ip}`);
          return;
        }
        // 发布给所有拨号方。**唯一**的地址来源 —— 没有第二处写死的常量兜底。
        setGuestLease(ip);
        this.stopGuestRegistration?.();
        this.stopGuestRegistration = ip ? publishGuestRegistration({
          guestId: name,
          hostname: `${name}.local`,
          ip,
          mac: macToString(mac),
          sessionId: guestSessionId,
        }) : null;
        // Publish this tab's name record once the lease is known; setRecord
        // re-announces on every lease change. Mirror the liveness guard: only
        // if the responder is still the one we started.
        if (ip && this.mdns === responder) responder.setRecord(`${name}.local`, ip);
        console.log(`[dhcp] tab "${name}" → guest ${ip ?? "(池满,没分到)"}`);
      } catch (e) {
        console.warn("[dhcp] 服务端起不来:", e);
      }
    };
    void poll();
  }

  /**
   * mDNS/DNS responder health for NetworkPanel (finding #5): "off" before
   * start, "up" while it can answer, "down" once its member died post-open.
   */
  getMdnsHealth(): "off" | "up" | "down" {
    return this.mdnsHealth;
  }

  /**
   * Watch the default-on mDNS/DNS responder AFTER it opens. attach()'s .catch
   * only sees pre-open failures; a member that opens then the hub drops (or
   * that never reaches a usable state) is otherwise invisible — yet the guest
   * already got INFRA_MEMBER_IP as its DHCP option-6 DNS, so every guest name
   * lookup would then hang against a dead nameserver with no signal anywhere
   * (review finding #5). We must NOT silently swallow that.
   *
   * On a down transition: a loud warning AND mdnsHealth="down" (getMdnsHealth,
   * for the panel to render DOWN truthfully) AND dhcp.setDns(null) so DHCP stops
   * advertising option 6 — leases granted while the responder is down never
   * point at the dead nameserver (finding #5 option A). On the reverse up
   * transition it calls setDns(INFRA_MEMBER_IP) to resume advertising.
   *
   * Known limit (honest boundary): option 6 only shapes leases granted AFTER the
   * change. A guest already holding a lease with a dead .2 is not helped —
   * udhcpc -n -q does not renew, so the stale option lingers until reboot.
   */
  private watchMdnsHealth(responder: MdnsResponder, server: DhcpServer, name: string): void {
    this.mdnsHealth = "up";
    // attach() has resolved => the responder is open => confirmed healthy. Now
    // (and only now) start advertising it as the guest's DNS. The server was
    // built with dns:null, so no lease before this point could point at an
    // unconfirmed nameserver (finding #5 option A; safer-of-two: wait-for-health
    // rather than advertise-optimistically-then-withdraw). Liveness-guarded on
    // this.dhcp===server, same shape as startDhcp, so we never poke a
    // detached/replaced server.
    if (this.dhcp === server) server.setDns(responder.ip);
    const tick = () => {
      if (this.mdns !== responder) return; // replaced/destroyed — stop reacting
      const healthy = responder.isHealthy();
      if (!healthy && this.mdnsHealth !== "down") {
        this.mdnsHealth = "down";
        // Option A: stop advertising option 6 so leases granted from now on are
        // not handed the dead .2. Liveness-guarded (this.dhcp===server).
        if (this.dhcp === server) server.setDns(null);
        console.warn(
          `[mdns] tab "${name}" 的 responder 在 open 之后掉线 —— 已停发 DHCP option 6,` +
            `新租约不再拿到 ${responder.ip};但已经持租的 guest 仍指向死的 .2` +
            `(udhcpc -n 不续租),名字解析会挂在死服务器上。`,
        );
      } else if (healthy && this.mdnsHealth === "down") {
        this.mdnsHealth = "up"; // transport recovered (e.g. ws reconnect)
        if (this.dhcp === server) server.setDns(responder.ip); // resume option 6
        console.log(`[mdns] tab "${name}" 的 responder 已恢复,恢复发 DHCP option 6`);
      }
    };
    this.mdnsHealthTimer = setInterval(tick, 1000);
  }

  getNetworkState(): NetworkState | null {
    return this._networkState;
  }

  onNetworkStateChange(cb: (state: NetworkState) => void): () => void {
    this.stateListeners.push(cb);
    return () => {
      this.stateListeners = this.stateListeners.filter((l) => l !== cb);
    };
  }

  destroy(): void {
    this.stopGuestRegistration?.();
    this.stopGuestRegistration = null;
    this.dhcp?.detach();
    this.dhcp = null;
    if (this.mdnsHealthTimer) {
      clearInterval(this.mdnsHealthTimer);
      this.mdnsHealthTimer = null;
    }
    this.mdnsHealth = "off";
    this.mdns?.detach();
    this.mdns = null;
    setGuestLease(null);
    this.transport?.destroy();
    this.emulator?.destroy();
    (window as unknown as { __v86Emulator?: unknown }).__v86Emulator = null;
    this.emulator = null;
    this.fetchAdapter = null;
    this.transport = null;
    this._networkState = null;
    this.stateListeners = [];
  }
}

