/**
 * vmConfig — 两个页面共用的一份 VM 启动配置。
 *
 * 极简终端页(@/ui/pages/TerminalHome)与实验台(@/ui/pages/LabHome)启动的必须
 * 是**同一台机器**:同一个内核/initramfs、同一段 cmdline、同一套 LAN 默认值。
 * 各写一份的下场是两页行为悄悄分叉,而分叉只会在"极简页录不到音/连不上"的时候
 * 才被发现。所以这些常量与默认值只留这一份。
 *
 * 默认值就是一键可用的姿势:**LAN 默认开启**(`?lan=0` 或 localStorage 退出)。
 * 极简页不暴露这个开关,但吃的是同一份默认值 —— 屏蔽的是 UI,不是能力。
 */

import type { V86InstanceConfig } from "@/vm/V86Instance";

// guest 的地址**不再是常量**。它由 tab 名哈希算出、由页面自己的 DHCP 服务端
// 下发(src/net/guestAddress.mjs + src/net/dhcpServer.mjs),运行期唯一来源是
// `@/net/guestLease`。原先这里的 `AUDIOD_GUEST_IP = "192.168.86.21"` 已删除 ——
// 它从来不是镜像自称的地址,只是"多处手敲了同一个数字"的约定;留着它就等于
// 保留第二套地址机制,会让拨号在租约没下发时静默走回老路。

/** ws-relay-hub 的同源入口(vite 代理 /__ws/net → :9000;https 页面自动成 wss)。 */
export function relayUrl(): string {
  return `${location.protocol === "https:" ? "wss:" : "ws:"}//${location.host}/__ws/net`;
}

/** LAN 开关初值:URL 参数 > localStorage > 默认 **ON**(一键化的前提)。 */
export function initialLanEnabled(): boolean {
  const p = new URLSearchParams(location.search);
  if (p.get("lan") === "1") return true;
  if (p.get("lan") === "0") return false;
  const ls = localStorage.getItem("v86_lan");
  return ls === null ? true : ls === "1";
}

/**
 * guest 镜像 + 内核 cmdline + 内存 + 网络。
 * `lanRelay` 给了就带 virtio relay 启动 —— LAN 是**启动期**配置,开关只对下一次
 * START 生效(NetworkPanel 里有同样的提示)。
 */
/**
 * guest 里的后台服务(audiod / sshd)**开机不自动起**(2026-08-18)——
 * 由 `aaud` / `assh` 显式启动,每条都有 --help。业务应用由外部 bundle
 * 注入后自行启动,基础镜像不替它们预留入口。
 *
 * 唯一的"自动"是内核 cmdline 上的 `autostart=`,而且必须显式点名。这里的规则:
 *   `?autostart=…`  显式覆盖(空串 = 什么都不起),优先级最高
 *   `?test` / `?testmode`  测试模式 → audiod,sshd
 *   其余(人正常打开页面)→ 什么都不起
 */
function autostartList(): string {
  const q = new URLSearchParams(location.search);
  const explicit = q.get("autostart");
  if (explicit !== null) return explicit.trim();
  if (q.has("test") || q.has("testmode")) return "audiod,sshd";
  return "";
}

export function buildVmConfig(lanRelay: string | undefined): V86InstanceConfig {
  const autostart = autostartList();
  return {
    bzimageUrl: "/images/alsa-bzimage.bin",
    initrdUrl: "/images/alsa-initramfs.gz",
    cmdline: "console=tty0 console=ttyS0,115200 rdinit=/init quiet loglevel=2 nomce"
      + " snd_sb16.port=0x220 snd_sb16.irq=5 snd_sb16.dma8=1 snd_sb16.dma16=5 snd_sb16.fm_port=-1"
      + (autostart ? ` autostart=${autostart}` : ""),
    memorySize: 128 * 1024 * 1024,
    networkConfig: { dnsMethod: "doh" },
    lanRelayUrl: lanRelay,
  };
}

