/**
 * TerminalHome — 唯一的页面。一个开机按钮 + 一个占满视口的串口终端。
 *
 * 用户原话:"页面太花哨了,做一个非常简洁的 web terminal 入口就行,其余所有功能
 * 先屏蔽,慢慢再加"。所以这一页上**只有一个动作**:
 *
 *   [开机 / 关机] —— 点下去把开机整串跑完:启动 VM → 等 guest shell 真的回话。
 *                     不需要用户先去别处开 LAN(LAN 默认就是开的,见 @/ui/vmConfig),
 *                     也不需要先去点别的面板。就绪与失败都在按钮旁边一行小字里说清。
 *
 * 剩下整屏都是终端(复用 @/ui/components/Terminal,xterm + FitAddon,自带
 * ResizeObserver,窗口缩放跟着 resize)。可输入可回显:VM 在跑时按键直接进 ttyS0。
 *
 * **例外只有一个:BuildFreshnessBanner。** 它不是功能,是护栏 —— 平时一个像素都
 * 不占,只在 build/libv86.js 与 v86/src 对不上时压顶。屏蔽它等于让人对着一份旧
 * 代码调试,而那正是它被造出来要防的事故(2026-08-15:build 落后 src 三个月,
 * 期间所有测试都是绿的)。所以它留下,而且不可关闭。
 *
 * ## 实验台的接线摘掉了(2026-08-24)
 *
 * 用户定的范围:**这一页只负责把 Linux 起起来,其余的在 shell 里实现**。
 * 于是 `@/ui/lab/LabPanel` 不再挂载,`?lab=1` 与 localStorage `v86_lab` 一并
 * 作废 —— 留一个不接任何东西的开关比没有更糟。
 *
 * 摘之前先确认过一件事,否则这一刀会砍掉阶梯上不可替代的东西:v86 唯一
 * 只有它能跑的那两条采集断言(`arecord.writes_file` /
 * `arecord.silence_no_garbage`,因为 qemu 的 SB16 没有 ADC)走的是
 * tests/lib/vm-runner 的无头 `bootVM({mode:"kernel-only"})` —— 直接对 guest
 * 敲 shell,一行都不经过页面上的面板。所以摘接线不影响它们。
 *
 * `useV86` 仍然全应用只调这一次,VM 的生命周期仍然钉在这一页上。
 *
 * ## 麦克风:默认要权限,静音交给浏览器(2026-08-24 用户定)
 *
 * 摘掉实验台之后,那个麦克风开关跟着没了 —— guest 里的 `arec` 于是只能录到
 * 静音,因为没人往 SB16 的 ADC 里喂样本。补法**不是把开关加回来**:页面上
 * "只有一个按钮"是一条护栏,新能力要绕着它走。
 *
 * 所以麦克风变成**默认就开**,而"我不想让它听"这件事交给宿主浏览器 ——
 * 标签页静音、站点权限、系统输入设备,那三处本来就是用户真正认得的开关,
 * 页面再造一个只会多一处需要同步的真值。
 *
 * 两个实现要点:
 *   1. 权限在**开机那一次用户手势里**就要 —— 拿到即停 track,只为把授权
 *      存下来。浏览器对没有手势的 getUserMedia 越来越不客气,而弹窗趁人
 *      还在等 VM 启动时出来,体感上是免费的。这条做法照搬当初 useOneClick
 *      验证过的那个。
 *   2. **麦克风失败不许挡开机**。拒了就拒了,顶栏如实写"未授权"并带上
 *      浏览器给的那个 name,VM 照常跑 —— 宁可显示取不到,不许假装有。
 *
 * **顶栏上那行小字 `tailnet`**(@/ui/components/TailnetPanel)留着:点开才展开
 * 面板,用来把这个标签页变成 tailnet 上的一个节点。它是 `<a>` 不是 `<button>`
 * —— 页面上"只有一个按钮"这条断言是护栏,新功能要绕着它走,不是改它。
 * 25MB 的 WASM 客户端只在用户真的点"连接"时才下载,首屏不受影响。
 */

import { useCallback, useEffect, useMemo, useRef, useState, type CSSProperties } from "react";
import { useV86 } from "@/vm/useV86";
import { VGAScreen } from "@/ui/components/VGAScreen";
import { Terminal, type TerminalHandle } from "@/ui/components/Terminal";
import { BuildFreshnessBanner, BuildFreshnessChip } from "@/ui/lab/BuildFreshness";
import { buildVmConfig, initialLanEnabled, relayUrl } from "@/ui/vmConfig";
import { waitSerialText } from "@/ui/waitSerialMarker";
import { TailnetPanel } from "@/ui/components/TailnetPanel";
import { ShareFolderBar } from "@/ui/lab/ShareFolderBar";
import { useShareVault } from "@/ui/lab/useShareVault";
import { HostDirectory } from "@/fs/hostDirectory";
import { HostShare } from "@/fs/hostShare";

type Phase = "off" | "booting" | "ready" | "error";

/** guest shell 等待上限。冷启动到 shell 就绪实测 1–2min(含 v86.wasm 下载)。 */
const SHELL_TIMEOUT_MS = 150_000;

const PHASE_TEXT: Record<Phase, string> = {
  off: "未开机",
  booting: "启动中,等 guest shell…",
  ready: "shell 就绪,可以敲命令了",
  error: "启动失败",
};

export function TerminalHome() {
  // LAN 是启动期配置,由 @/ui/vmConfig 的默认值决定(URL 参数 > localStorage >
  // 默认开)。页面上没有开关 —— 从前那个开关在实验台的 NetworkPanel 里,面板
  // 摘掉后要改就改 URL 参数,或者进 guest 自己调。
  const [lanEnabled] = useState(initialLanEnabled);
  const config = useMemo(
    () => buildVmConfig(lanEnabled ? relayUrl() : undefined),
    [lanEnabled],
  );

  const share = useShareVault();
  const hostShareRef = useRef<HostShare | null>(null);
  useEffect(() => {
    hostShareRef.current?.dispose();
    hostShareRef.current = share.root && share.permission === "granted"
      ? new HostShare(new HostDirectory(share.root))
      : new HostShare(null);
    return () => { hostShareRef.current?.dispose(); hostShareRef.current = null; };
  }, [share.root, share.permission]);

  const onBeforeStop = useCallback(async (emu: unknown) => {
    await hostShareRef.current?.flushFromGuest(emu);
  }, []);

  /** **全应用唯一的一次 `useV86`。** VM 的生命周期只挂在这一页上。 */
  const vm = useV86(config, { onBeforeStop });
  const {
    screenRef, error, running, start, stop, serialSend, onSerialOutput,
    audioReady, micEnabled, micStarting, micFailure, toggleMic,
    getEmulator,
  } = vm;

  useEffect(() => {
    if (!running || !share.root || share.permission !== "granted") return;
    const emu = getEmulator();
    if (emu) void hostShareRef.current?.syncToGuest(emu);
  }, [running, share.root, share.permission, getEmulator]);
  useEffect(() => {
    if (running) return;
    const emu = getEmulator();
    if (emu) void hostShareRef.current?.flushFromGuest(emu);
  }, [running, getEmulator]);

  const termRef = useRef<TerminalHandle>(null);
  const charSubsRef = useRef<Set<(ch: string) => void>>(new Set());
  const [phase, setPhase] = useState<Phase>("off");
  const [failure, setFailure] = useState<string | null>(null);
  const [shareOpen, setShareOpen] = useState(false);

  // 串口输出 → 终端 + 字符订阅者。开机流程被动等待 shell prompt 用的就是后者。
  // `onSerialOutput` 只收**一个**回调,所以订阅分发必须钉在这一层:谁要是
  // 自己去调它,会把终端的输出顶掉。
  useEffect(() => onSerialOutput((ch) => {
    termRef.current?.write(ch);
    for (const cb of charSubsRef.current) cb(ch);
  }), [onSerialOutput]);

  const bridge = useMemo(() => ({
    send: (data: string) => serialSend(data),
    onChar: (cb: (ch: string) => void) => {
      charSubsRef.current.add(cb);
      return () => { charSubsRef.current.delete(cb); };
    },
  }), [serialSend]);

  // 长流程中途 re-render 后闭包会过期,`running` 现取现用。
  const runningRef = useRef(running);
  runningRef.current = running;

  // 长流程里 bridge 的身份可能因为 serialSend 换引用而变;等待本身不该因此重开。
  const bridgeRef = useRef(bridge);
  bridgeRef.current = bridge;

  /**
   * 顶栏那句机器状态,**只跟着观察到的事实走**。
   *
   * 它以前只由这一页的开机按钮写(onPower 里那四处 setPhase)。而
   * `ensure.ts:99` 的 `vm` 需求是拿一个裸 `c.start()` 满足的 —— 也就是说
   * 「备好环境」这个被文档指定为第一下点的按钮,走的是一条永远不会推进
   * `phase` 的路。结果:整场已开机、正在录音的会话里,顶栏一直写着「未开机」,
   * 而 12–40px 外的那个按钮(读的是活的 `running`)写着「关机」。反向也成立:
   * TransportBar 的 STOP 直接接 vm.stop,停机之后顶栏还挂着「shell 就绪」。
   *
   * 修法不是再加一个 setter 去同步两份拷贝(那只是把两份变成三份),而是让这句
   * 话读**一个**来源:VM 在不在跑(useV86 的 running),以及 guest shell 有没有
   * 真的回话(一次性口令原样回环)。谁点的开机、从哪条路开的,都不再重要。
   */
  useEffect(() => {
    if (!running) { setPhase("off"); setFailure(null); return; }
    setPhase((p) => (p === "ready" ? p : "booting"));
    setFailure(null);
    const ac = new AbortController();
    // getty 只有在 /bin/sh 已接管 ttyS0 后才会画出这个 prompt。被动等它即可，
    // 不向用户正在看的终端注入 readiness 命令与回显。
    waitSerialText(bridgeRef.current, "~ # ", SHELL_TIMEOUT_MS, ac.signal)
      .then(() => { if (!ac.signal.aborted) setPhase("ready"); })
      .catch((e: unknown) => {
        // 放弃等待不是失败:机器停了/换了一轮,这一轮的结论作废即可。
        if (ac.signal.aborted) return;
        setFailure(e instanceof Error ? e.message : String(e));
        setPhase("error");
      });
    return () => ac.abort();
  }, [running]);

  /**
   * 只为把授权存下来:拿到就把 track 停掉。**不 await** —— 弹窗要趁用户还在
   * 等 VM 启动时出来,而不是让开机排在弹窗后面。拒了就拒了,这里不报错,
   * 真正的失败归因由下面那条自动开麦生成(它拿得到浏览器给的 name)。
   */
  const bankMicPermission = useCallback(() => {
    navigator.mediaDevices?.getUserMedia({ audio: true })
      .then((s) => s.getTracks().forEach((t) => t.stop()))
      .catch(() => { /* 开机不该因为麦克风被拒而失败 */ });
  }, []);

  /** 按钮只管开关机;顶栏那句话由上面那条观察生成,不在这里写。 */
  const onPower = useCallback(() => {
    if (runningRef.current) { stop(); return; }
    // 顺序有意:先在这次手势里要权限,再启动 VM。
    bankMicPermission();
    start();
  }, [start, stop, bankMicPermission]);

  /**
   * VM 起来、声卡的下行链路也就位之后自动开麦。
   *
   * 判据是 `audioReady`(真的从 emulator 上取到了 mic downsampler),不是
   * "VM 在跑" —— 采到的样本得有地方去,早开一步就是往一个还不存在的设备里
   * 灌数据。失败过一次就不再试:micFailure 一旦有值这条就熄火,免得对着一个
   * 已经拒绝的权限每 300ms 弹一次。
   */
  useEffect(() => {
    if (!running || !audioReady) return;
    if (micEnabled || micStarting || micFailure) return;
    void toggleMic();
  }, [running, audioReady, micEnabled, micStarting, micFailure, toggleMic]);

  /** 四态,一一对应顶栏那句话。没有第五种"大概在开着"。 */
  const micState = micFailure ? "denied"
    : micEnabled ? "on"
    : micStarting ? "starting"
    : "off";
  const micText = micState === "on" ? "麦克风 已开(静音请用浏览器)"
    : micState === "starting" ? "麦克风 请求中"
    : micState === "denied" ? `麦克风 未授权(${micFailure?.name ?? "?"})`
    : "麦克风 未开";

  const message = failure ?? error;

  return (
    <div style={s.page}>
      {/* 唯一的例外:平时不显示,只在 libv86 与 src 不一致时压顶(见文件头注释) */}
      <BuildFreshnessBanner />

      <div style={s.bar}>
        <button
          data-testid="power"
          data-running={running ? "1" : "0"}
          style={running ? { ...s.power, ...s.powerOn } : s.power}
          onClick={onPower}
        >
          {running ? "关机" : "开机"}
        </button>
        <span data-testid="vm-phase" data-phase={phase} style={s.status}>
          {PHASE_TEXT[phase]}
        </span>
        {/* 原来在终端那层假窗框上,窗框去掉后并到这条唯一的顶栏 */}
        <span style={s.status}>· Serial Console (ttyS0)</span>
        {/* 一行小字,不是开关:静音归浏览器管(见文件头注)。取不到就说取不到。 */}
        <span style={s.status} data-testid="mic-state" data-mic={micState}>
          {micText}
        </span>
        {message && <span style={s.error}>{message}</span>}
        <div style={{ flex: 1 }} />
        <span style={s.status}>Ctrl+Shift+C 复制 · Ctrl+Shift+V 粘贴</span>
        {/* 构建新鲜度:页面级信息,原来挂在浮窗标题栏上,窗框去掉后回到这条唯一的顶栏 */}
        <BuildFreshnessChip />
        <button
          type="button"
          data-testid="host-share-toggle"
          onClick={() => setShareOpen((open) => !open)}
          style={s.shareToggle}
          title="打开本机目录映射设置"
        >
          Share {share.root ? `· ${share.root.name}` : "· 未连接"}
        </button>
        {/* tailnet 入口:同样是一行小字,点开才有面板;连上后小字变成本页节点的 tailnet IP */}
        <TailnetPanel />
      </div>
      {shareOpen && (
        <div style={s.sharePanel} data-testid="host-share-panel">
          <ShareFolderBar vault={share} />
        </div>
      )}

      <div style={s.body}>
        <Terminal ref={termRef} onData={running ? serialSend : undefined} height={9999} />
      </div>

      {/* v86 初始化要有个屏幕容器,藏起来即可(testid 让"页面上没有画布"这类断言能把它排除) */}
      <div data-testid="vga" style={s.hiddenScreen}>
        <VGAScreen screenRef={screenRef} />
      </div>
    </div>
  );
}

const s = {
  page: {
    height: "100vh",
    overflow: "hidden",
    background: "#0d1117",
