#!/usr/bin/env node
// tests/test-terminal-home.mjs — 默认入口(极简终端页)的端到端验收。
//
// 用户原话:"页面太花哨了,做一个非常简洁的 web terminal 入口就行,其余所有功能
// 先屏蔽,慢慢再加"。这条用例钉住的就是那句话的两半:
//
//   **简** —— 冷开 `/`(无参数、无 localStorage)拿到的必须是极简页:一键条、
//             录音列表、回执卡、示波器/频谱/时间线、寄存器、测试套、网络面板、
//             录音源栏……一个都不在 DOM 里。页面上的按钮**只有一个**(开机/关机)。
//             唯一允许多出来的是构建过期横幅 —— 它是护栏不是功能,平时不显示,
//             多出那个按钮本身就说明 libv86 与 src 对不上,该红。
//
//   **能用** —— 点一次开机就把流程整串跑完(不需要先去别处开 LAN),终端出 shell
//             提示符,敲 `uname -a` 有回显。
//
// 前置:vite dev 在 5173。用法:node tests/test-terminal-home.mjs
// 注:未纳入 run-suite 的 fast/full 两档(那两档的清单是既有守护矩阵);
//     单独跑,或按需自行加进 tests/run-suite.mjs。

import { chromium } from "playwright";

const PAGE_URL = process.env.PAGE_URL || "http://localhost:5173/";

const t0 = Date.now();
const ts = () => `[${((Date.now() - t0) / 1000).toFixed(1)}s]`;
let failures = 0;
function step(name, ok, detail = "") {
  console.log(`${ts()} [${ok ? "PASS" : "FAIL"}] ${name}${detail ? " — " + detail : ""}`);
  if (!ok) failures++;
  return ok;
}

/** 被屏蔽的实验台部件:选择器 → 人话。一个都不许出现在默认页上。 */
const BLOCKED = [
  ['[data-testid="oneclick"]', "一键录音条 OneClickBar"],
  ['[data-testid="recordings-list"]', "录音列表 RecordingsList"],
  ['[data-testid="share-folder"]', "存储位置栏 ShareFolderBar"],
  ['[data-testid="provenance"]', "出处回执卡 ProvenanceCard"],
  ['[data-testid="network-panel"]', "网络面板 NetworkPanel"],
  ['[data-testid="rec-dest"]', "录音源状态栏 RecordingSource"],
  ['[data-testid="rec-link-toggle"]', "TransportBar 的 REC LINK 切换"],
];

async function main() {
  const browser = await chromium.launch({
    headless: process.env.HEADFUL !== "1",
    args: [
      "--use-fake-ui-for-media-stream",
      "--use-fake-device-for-media-stream",
      "--autoplay-policy=no-user-gesture-required",
      "--no-sandbox",
    ],
  });
  // 冷页面:全新 context = 空 localStorage,拿到的必须是默认入口
  const ctx = await browser.newContext({ permissions: ["microphone"], bypassCSP: true });
  const page = await ctx.newPage();
  const pageErrors = [];
  page.on("pageerror", (e) => { pageErrors.push(e.message); console.log(`[pageerror] ${e.message}`); });

  try {
    await page.goto(PAGE_URL, { waitUntil: "domcontentloaded", timeout: 30_000 });
    await page.waitForSelector('[data-testid="power"]', { timeout: 15_000 });
    step("冷开 / 落在极简终端页(有开机按钮)", true);

    // ── 一、被屏蔽的组件确实不在 ────────────────────────────────────────────
    for (const [sel, human] of BLOCKED) {
      const n = await page.locator(sel).count();
      step(`屏蔽:${human}`, n === 0, n === 0 ? sel : `${sel} 命中 ${n} 个`);
    }

    // 画布类面板(SignalScope/SpectrumAnalyzer/PipelineTimeline)——
    // v86 初始化要的那块隐藏 VGA 里也有个 canvas,它不算,按 testid 排除。
    const stray = await page.evaluate(() =>
      [...document.querySelectorAll("canvas")].filter((c) => !c.closest('[data-testid="vga"]')).length);
    step("屏蔽:示波器/频谱/时间线(页面上没有别的画布)", stray === 0, `多余 canvas ${stray} 个`);

    // xterm 的终端本体必须在(屏蔽的是花哨,不是终端)
    step("终端在场(xterm 已挂载)", (await page.locator(".xterm").count()) === 1);

    // ── 二、页面上只有一个动作 ──────────────────────────────────────────────
    const btns = await page.locator("button").allInnerTexts();
    step(
      "页面上只有一个按钮(开机/关机)",
      btns.length === 1,
      btns.length === 1 ? JSON.stringify(btns) : `实际 ${btns.length} 个:${JSON.stringify(btns)}(多出的若是"展开/收起",说明构建过期横幅在显示 —— 那是护栏,先修 libv86)`,
    );

    // ── 三、开机:一次点击串完全程 ──────────────────────────────────────────
    const powerLabel = await page.locator('[data-testid="power"]').innerText();
    step("按钮初态是「开机」", powerLabel.trim() === "开机", powerLabel);

    await page.locator('[data-testid="power"]').click();
    await page.waitForFunction(
      () => document.querySelector('[data-testid="vm-phase"]')?.dataset.phase === "booting",
      null, { timeout: 10_000 },
    );
    step("点开机后进入 booting(VM 已启动)", true);

    await page.waitForFunction(
      () => document.querySelector('[data-testid="vm-phase"]')?.dataset.phase === "ready",
      null, { timeout: 180_000, polling: 1000 },
    );
    step("guest shell 就绪(全程只点了一次,没碰任何别的开关)", true);
    step("按钮变成「关机」", (await page.locator('[data-testid="power"]').innerText()).trim() === "关机");

    // ── 四、终端真的是终端:出提示符、能输入、有回显 ────────────────────────
    const termText = async () => page.locator(".xterm-rows").innerText();
    const boot = await termText();
    step("终端出现 shell 提示符", /[/~]\s?#/.test(boot), JSON.stringify(boot.slice(-80)));
    step("启动过程不向用户终端注入 TT_READY 探针", !boot.includes("TT_READY"), JSON.stringify(boot.slice(-160)));
    const knownBootNoise = [
      "no OPL device",
      "Unable to init MCE device",
      "can't create /proc/sys/kernel/hotplug",
    ].filter(message => boot.includes(message));
    step("启动日志无已知硬件探测与 hotplug 告警", knownBootNoise.length === 0, JSON.stringify(knownBootNoise));

    await page.locator(".xterm").click();          // 焦点给 xterm
    await page.keyboard.type("uname -a");
    await page.keyboard.press("Enter");
    await page.waitForFunction(
      () => /Linux\s+\S+\s+\d+\.\d+/.test(document.querySelector(".xterm-rows")?.innerText || ""),
      null, { timeout: 30_000, polling: 500 },
    );
    const after = await termText();
    const echoed = after.includes("uname -a");
    const answered = /Linux\s+\S+\s+\d+\.\d+/.exec(after)?.[0] ?? "";
    step("输入 uname -a:命令回显", echoed);
    step("输入 uname -a:guest 有应答", !!answered, answered);

    // ── 五、缩放跟随 ────────────────────────────────────────────────────────
    const w0 = await page.evaluate(() => document.querySelector(".xterm-screen")?.clientWidth ?? 0);
    await page.setViewportSize({ width: 700, height: 620 });
    await page.waitForTimeout(1200);
    const w1 = await page.evaluate(() => document.querySelector(".xterm-screen")?.clientWidth ?? 0);
    step("窗口缩放后终端跟着 resize", w1 > 0 && w1 < w0, `${w0}px → ${w1}px`);

    // ── 六、实验台入口**不该**还在(2026-08-24 摘接线)──────────────────
    // 这两条从前是反过来写的:断言角落那行小字在、断言 ?lab=1 进得去、实验台
    // 一件没少。用户把范围收到"这一页只负责把 Linux 起起来"之后,那些断言钉的
    // 就是一个不该存在的东西了 —— 所以不是搬走,是掉个头:同一件事,现在要求
    // 它**不在**。留一个不接任何东西的开关比没有更糟。
    step("角落没有实验台入口", await page.locator('[data-testid="lab-toggle"]').count() === 0);
    step("?lab=1 不再挂出面板", await (async () => {
      const p2 = await ctx.newPage();
      p2.on("pageerror", (e) => pageErrors.push(`[?lab=1] ${e.message}`));
      await p2.goto(PAGE_URL + (PAGE_URL.includes("?") ? "&" : "?") + "lab=1",
        { waitUntil: "domcontentloaded", timeout: 30_000 });
      const n = await p2.locator('[data-testid="lab-panel"]').count();
      await p2.close();
      return n === 0;
    })(), "旧链接/书签还会有人点,进来得是同一个极简页,不是一个半死的面板");

    // ── 七、麦克风:默认要权限,静音交给浏览器 ──────────────────────────
    // 摘掉面板后那个麦克风开关没了,补法是**默认就开**(见 TerminalHome 头注)。
    // 这条钉的是"开机之后它真的自己起来了",不是"代码里写了自动开" ——
    // 判据取自页面自己印出来的状态,浏览器授权由 --use-fake-* 提供。
    let micState = null;
    for (let i = 0; i < 60; i++) {
      micState = await page.locator('[data-testid="mic-state"]').getAttribute("data-mic");
      if (micState === "on" || micState === "denied") break;
      await page.waitForTimeout(1000);
    }
    step("开机后麦克风自动就位", micState === "on",
      "顶栏原话:" + await page.locator('[data-testid="mic-state"]').innerText());

    step("全程无未捕获异常", pageErrors.length === 0, pageErrors.join(" | "));
  } catch (e) {
    step("用例执行", false, e?.message || String(e));
  } finally {
    await browser.close();
  }

  console.log(`\nRESULT: ${failures === 0 ? "PASS" : "FAIL"}${failures ? ` (${failures} 条)` : ""}`);
  process.exit(failures === 0 ? 0 : 1);
}

main();

