    #!/usr/bin/env node
    /**
     * test-topbar-panels.mjs — E2E behavior verification for topbar popup panels (Share & Tailnet):
     *   1. Both entry points match ghost pill specification (11px, 3px 8px padding, border, grey/green);
     *   2. Panel mutual exclusion: opening one panel automatically closes the other;
     *   3. Coordinate alignment: both panels align their top position to PANEL_TOP (48px);
     *   4. Outside-click dismiss: clicking on blank area outside panels closes the active panel;
     *   5. Escape key dismiss: pressing Escape key closes the active panel;
     *   6. Inside-panel clicks do not inadvertently dismiss the panel.
     *
     * Prerequisite: vite dev on 5173. Usage: node tests/test-topbar-panels.mjs
     */

    import { chromium } from "playwright";

    const PAGE_URL = process.env.PAGE_URL || "http://localhost:5173/";

    const t0 = Date.now();
    const ts = () => `[${((Date.now() - t0) / 1000).toFixed(1)}s]`;
    let failures = 0;

    function step(name, ok, detail = "") {
      console.log(`${ts()} [${ok ? "PASS" : "FAIL"}] ${name}${detail ? " — " + detail : ""}`);
      if (!ok) failures++;
      return ok;
    }

    const browser = await chromium.launch({
      headless: process.env.HEADFUL !== "1",
      args: ["--no-sandbox"],
    });
    const ctx = await browser.newContext();
    const page = await ctx.newPage();

    const pageErrors = [];
    page.on("pageerror", (e) => {
      pageErrors.push(e.message);
      console.log(`${ts()} [pageerror] ${e.message}`);
    });

    try {
      // ── 1. Default clean terminal home state ───────────────────────────────────
      await page.goto(PAGE_URL, { waitUntil: "domcontentloaded", timeout: 30_000 });
      await page.waitForSelector('[data-testid="power"]', { timeout: 15_000 });

      step("Default page loaded successfully with power button", true);
      step("Default page has no Share panel", (await page.locator('[data-testid="host-share-panel"]').count()) === 0);
      step("Default page has no Tailnet panel", (await page.locator('[data-testid="tailnet-panel"]').count()) === 0);

      const btns = await page.locator("button").allInnerTexts();
      step("Default page has exactly 1 button (power)", btns.length === 1, JSON.stringify(btns));

      // ── 2. Ghost pill visual spec (Share & Tailnet entries) ────────────────────
      const shareToggle = page.locator('[data-testid="host-share-toggle"]');
      const tailnetEntry = page.locator('[data-testid="tailnet-entry"]');

      step("Share entry is an <a> element instead of <button>",
        (await shareToggle.evaluate((el) => el.tagName.toLowerCase())) === "a");
      step("Tailnet entry is an <a> element instead of <button>",
        (await tailnetEntry.evaluate((el) => el.tagName.toLowerCase())) === "a");

      const shareStyle = await shareToggle.evaluate((el) => {
        const cs = window.getComputedStyle(el);
        return { fontSize: cs.fontSize, borderStyle: cs.borderTopStyle, color: cs.color };
      });
      const tailnetStyle = await tailnetEntry.evaluate((el) => {
        const cs = window.getComputedStyle(el);
        return { fontSize: cs.fontSize, borderStyle: cs.borderTopStyle, color: cs.color };
      });

      step("Share entry font size is 11px", shareStyle.fontSize === "11px", shareStyle.fontSize);
      step("Tailnet entry font size is 11px", tailnetStyle.fontSize === "11px", tailnetStyle.fontSize);
      step("Share entry has a solid border", shareStyle.borderStyle === "solid", shareStyle.borderStyle);
      step("Tailnet entry has a solid border", tailnetStyle.borderStyle === "solid", tailnetStyle.borderStyle);
      step("Share entry disconnected color is #8b949e",
        shareStyle.color === "rgb(139, 148, 158)", shareStyle.color);
      step("Tailnet entry disconnected color is #8b949e",
        tailnetStyle.color === "rgb(139, 148, 158)", tailnetStyle.color);

      // ── 3. Open Share panel & coordinate verification ──────────────────────────
      await shareToggle.click();
      await page.waitForSelector('[data-testid="host-share-panel"]', { timeout: 5_000 });

      step("Clicking Share entry opens Share panel",
        (await page.locator('[data-testid="host-share-panel"]').isVisible()));
      step("Tailnet panel is not in DOM when Share panel is open",
        (await page.locator('[data-testid="tailnet-panel"]').count()) === 0);

      const shareBox = await page.locator('[data-testid="host-share-panel"]').boundingBox();
      step("Share panel top coordinate aligns to 48px",
        shareBox !== null && Math.round(shareBox.y) === 48,
        `y=${shareBox?.y}`);

      // ── 4. Mutual exclusion: Share open -> click Tailnet entry ─────────────────
      await tailnetEntry.click();
      await page.waitForSelector('[data-testid="tailnet-panel"]', { timeout: 5_000 });

      step("Clicking Tailnet entry opens Tailnet panel",
        (await page.locator('[data-testid="tailnet-panel"]').isVisible()));
      step("Opening Tailnet panel automatically closes Share panel (mutual exclusion)",
        (await page.locator('[data-testid="host-share-panel"]').count()) === 0);

      const tailnetBox = await page.locator('[data-testid="tailnet-panel"]').boundingBox();
      step("Tailnet panel top coordinate aligns to 48px",
        tailnetBox !== null && Math.round(tailnetBox.y) === 48,
        `y=${tailnetBox?.y}`);

      // ── 5. Inside panel click does not dismiss panel ───────────────────────────
      await page.locator('[data-testid="tailnet-hostname"]').click();
      step("Clicking input inside Tailnet panel preserves panel open state",
        (await page.locator('[data-testid="tailnet-panel"]').isVisible()));

      // ── 6. Outside click dismissal ─────────────────────────────────────────────
      await page.mouse.click(20, 200);
      await page.waitForTimeout(200);

      step("Clicking outside blank area automatically closes Tailnet panel",
        (await page.locator('[data-testid="tailnet-panel"]').count()) === 0);
      step("Both panels remain closed after outside click",
        (await page.locator('[data-testid="host-share-panel"]').count()) === 0 &&
        (await page.locator('[data-testid="tailnet-panel"]').count()) === 0);

      // ── 7. Reverse mutual exclusion: Tailnet open -> click Share entry ─────────
      await tailnetEntry.click();
      await page.waitForSelector('[data-testid="tailnet-panel"]', { timeout: 5_000 });
      step("Re-opening Tailnet panel succeeds",
        (await page.locator('[data-testid="tailnet-panel"]').isVisible()));

      await shareToggle.click();
      await page.waitForSelector('[data-testid="host-share-panel"]', { timeout: 5_000 });
      step("Clicking Share entry while Tailnet is open opens Share panel",
        (await page.locator('[data-testid="host-share-panel"]').isVisible()));
      step("Opening Share panel automatically closes Tailnet panel (reverse mutual exclusion)",
        (await page.locator('[data-testid="tailnet-panel"]').count()) === 0);

      // ── 8. Escape key dismiss ──────────────────────────────────────────────────
      await page.keyboard.press("Escape");
      await page.waitForTimeout(200);

      step("Pressing Escape key closes Share panel",
        (await page.locator('[data-testid="host-share-panel"]').count()) === 0);

      // ── 9. Escape key dismiss on Tailnet panel ──────────────────────────────────
      await tailnetEntry.click();
      await page.waitForSelector('[data-testid="tailnet-panel"]', { timeout: 5_000 });
      await page.keyboard.press("Escape");
      await page.waitForTimeout(200);

      step("Pressing Escape key closes Tailnet panel",
        (await page.locator('[data-testid="tailnet-panel"]').count()) === 0);

      step("No uncaught page errors throughout execution", pageErrors.length === 0, pageErrors.join(", "));
    } catch (e) {
      step("Overall test flow", false, e?.message ?? String(e));
    } finally {
      await browser.close();
    }

    console.log(failures === 0 ? "\nALL PASS" : `\n${failures} FAILURES`);
    process.exit(failures === 0 ? 0 : 1);

