    #!/usr/bin/env node
    /**
     * test-tailnet-ip-copy.mjs — Real Playwright behavior test for Tailnet IP click-to-copy.
     *
     * Verifies:
     *   1. When connected, `[data-testid="tailnet-ip-copy"]` displays the node's self IP.
     *   2. Clicking the IP copies the exact IP to system clipboard via navigator.clipboard.writeText.
     *   3. navigator.clipboard.readText() returns the exact IP copied.
     *   4. Clicking the IP shows temporary feedback ("已复制 ✓") and reverts after 1.5s.
     *   5. Clicking the IP does NOT trigger or toggle the Tailnet panel (stopPropagation & outside-click isolation).
     *   6. Clicking the IP when the panel is closed preserves the closed state while still copying.
     *
     * Uses Playwright's route interception on /tailscale/pkg.js (PKG_STUB) so it runs
     * completely offline in ~1s without downloading the 25MB wasm.
     *
     * Prerequisite: vite dev on 5173. Usage: node tests/test-tailnet-ip-copy.mjs
     */

    import { chromium } from "playwright";

    const PAGE_URL = process.env.PAGE_URL || "http://localhost:5173/";
    const NODE_NAME = "v86-copy-probe";
    const SELF_IP = "100.101.102.103";

    const t0 = Date.now();
    const ts = () => `[${((Date.now() - t0) / 1000).toFixed(1)}s]`;
    let failures = 0;
    function step(name, ok, detail = "") {
      console.log(`${ts()} [${ok ? "PASS" : "FAIL"}] ${name}${detail ? " — " + detail : ""}`);
      if (!ok) failures++;
      return ok;
    }

    const PKG_STUB = `
    export async function createIPN(config) {
      window.__tsStubConfig = config;
      return {
        run(cb) {
          window.__tsStub = cb;
          cb.notifyState("NeedsLogin");
        },
        login() { window.__tsStubLogins = (window.__tsStubLogins || 0) + 1; },
        logout() { window.__tsStub && window.__tsStub.notifyState("Stopped"); },
        async fetch() { return { status: 0, statusText: "stub", text: async () => "" }; },
      };
    }
    `;

    function netmap(selfIP) {
      const self = {
        name: `${NODE_NAME}.tailstub.ts.net`,
        addresses: [selfIP, "fd7a:115c:a1e0::1"],
        machineKey: "mkey:stub",
        nodeKey: "nodekey:stub",
        machineStatus: "Machine authorized",
      };
      return { self, peers: [], lockedOut: false };
    }

    async function feed(page, nm) {
      await page.evaluate((json) => {
        window.__tsStub.notifyNetMap(json);
        window.__tsStub.notifyState("Running");
      }, JSON.stringify(nm));
    }

    const browser = await chromium.launch({
      headless: process.env.HEADFUL !== "1",
      args: ["--no-sandbox"],
    });
    const ctx = await browser.newContext({
      permissions: ["clipboard-read", "clipboard-write"],
    });

    await ctx.route("**/tailscale/pkg.js", (r) =>
      r.fulfill({ status: 200, contentType: "text/javascript", body: PKG_STUB }));
    await ctx.route("**/tailscale/main.wasm", (r) =>
      r.fulfill({ status: 200, contentType: "application/wasm", body: "" }));

    const page = await ctx.newPage();
    const pageErrors = [];
    page.on("pageerror", (e) => {
      pageErrors.push(e.message);
      console.log(`${ts()} [pageerror] ${e.message}`);
    });

    try {
      // ── 1. Open panel and connect using mock WASM ──────────────────────────────
      await page.goto(`${PAGE_URL}?tailnet=1`, { waitUntil: "domcontentloaded", timeout: 30_000 });
      await page.waitForSelector('[data-testid="tailnet-panel"]', { timeout: 15_000 });

      step("Tailnet panel opened via ?tailnet=1", true);
      step("Before connection, tailnet-ip-copy is not rendered",
        (await page.locator('[data-testid="tailnet-ip-copy"]').count()) === 0);

      await page.locator('[data-testid="tailnet-hostname"]').fill(NODE_NAME);
      await page.locator('[data-testid="tailnet-authkey"]').fill("tskey-auth-stub");
      const remember = page.locator('[data-testid="tailnet-remember"]');
      if (await remember.isChecked()) await remember.uncheck();

      await page.locator('[data-testid="tailnet-connect"]').click();
      await page.waitForFunction(() => typeof window.__tsStub === "object" && window.__tsStub !== null,
        null, { timeout: 15_000, polling: 100 });

      await feed(page, netmap(SELF_IP));

      await page.waitForSelector('[data-testid="tailnet-ip-copy"]', { timeout: 5_000 });
      step("Node reaches Running state and tailnet-ip-copy element appears", true);

      const ipText = (await page.locator('[data-testid="tailnet-ip-copy"]').innerText()).trim();
      step("tailnet-ip-copy initially displays node self IP", ipText === SELF_IP, ipText);

      // ── 2. Click IP element and verify real clipboard content ──────────────────
      await page.locator('[data-testid="tailnet-ip-copy"]').click();

      const clipText = await page.evaluate(async () => navigator.clipboard.readText());
      step("Clicking IP copies exact IP to clipboard", clipText === SELF_IP, clipText);

      const feedbackText = (await page.locator('[data-testid="tailnet-ip-copy"]').innerText()).trim();
      step("Clicking IP triggers visual feedback '已复制 ✓'", feedbackText.includes("已复制"), feedbackText);

      const panelStillOpen = await page.locator('[data-testid="tailnet-panel"]').isVisible();
      step("Clicking IP does NOT dismiss or toggle the active panel", panelStillOpen);

      // ── 3. Verify feedback reverts back to IP after timeout ────────────────────
      await page.waitForTimeout(1600);
      const revertedText = (await page.locator('[data-testid="tailnet-ip-copy"]').innerText()).trim();
      step("Visual feedback reverts back to self IP after 1.5s", revertedText === SELF_IP, revertedText);

      // ── 4. Toggle panel closed via tailnet-entry, then click IP ────────────────
      await page.locator('[data-testid="tailnet-entry"]').click();
      await page.waitForTimeout(200);
      const panelClosed = (await page.locator('[data-testid="tailnet-panel"]').count()) === 0;
      step("Clicking tailnet-entry closes the Tailnet panel", panelClosed);

      // Clear clipboard to test re-copy when panel is closed
      await page.evaluate(async () => navigator.clipboard.writeText("cleared"));
      step("Clipboard cleared before closed-panel test",
        (await page.evaluate(async () => navigator.clipboard.readText())) === "cleared");

      await page.locator('[data-testid="tailnet-ip-copy"]').click();
      const clipTextClosed = await page.evaluate(async () => navigator.clipboard.readText());
      step("Clicking IP while panel is closed copies exact IP", clipTextClosed === SELF_IP, clipTextClosed);

      const panelRemainsClosed = (await page.locator('[data-testid="tailnet-panel"]').count()) === 0;
      step("Clicking IP while panel is closed does NOT open the panel", panelRemainsClosed);

      step("No uncaught page errors throughout execution", pageErrors.length === 0, pageErrors.join(", "));
    } catch (e) {
      step("Overall test execution", false, e?.message ?? String(e));
    } finally {
      await browser.close();
    }

    console.log(failures === 0 ? "\nALL PASS" : `\n${failures} FAILURES`);
    process.exit(failures === 0 ? 0 : 1);

