/** Browser-local directory adapter for the unified /share root. */
export const HOST_SHARE_DIRS = ["apps", "recordings", "config", "workspace"] as const;
export type HostShareDir = (typeof HOST_SHARE_DIRS)[number];

export interface HostFile { path: string; data: Uint8Array; mtime: number }

function safePath(path: string): string[] {
  if (!path || path.startsWith("/") || path.includes("\\")) throw new TypeError("unsafe HostShare path");
  const parts = path.split("/");
  if (parts.some((p) => !p || p === "." || p === "..")) throw new TypeError("unsafe HostShare path");
  if (!HOST_SHARE_DIRS.includes(parts[0] as HostShareDir)) throw new TypeError("path outside HostShare roots");
  return parts;
}

async function walk(dir: FileSystemDirectoryHandle, prefix: string, out: HostFile[]): Promise<void> {
  for await (const [name, handle] of dir.entries()) {
    const path = prefix ? `${prefix}/${name}` : name;
    if (handle.kind === "directory") await walk(handle as FileSystemDirectoryHandle, path, out);
    else {
      const f = await (handle as FileSystemFileHandle).getFile();
      out.push({ path, data: new Uint8Array(await f.arrayBuffer()), mtime: f.lastModified });
    }
  }
}

export class HostDirectory {
  constructor(readonly root: FileSystemDirectoryHandle) {}

  async readTree(): Promise<HostFile[]> {
    const out: HostFile[] = [];
    for (const name of HOST_SHARE_DIRS) {
      try { await walk(await this.root.getDirectoryHandle(name), name, out); }
      catch (e) { if (!(e instanceof DOMException && e.name === "NotFoundError")) throw e; }
    }
    return out;
  }

  async readFile(path: string): Promise<Uint8Array> {
    const parts = safePath(path); const name = parts.pop()!;
    let dir = this.root;
    for (const part of parts) dir = await dir.getDirectoryHandle(part);
    const buf = await (await dir.getFileHandle(name)).getFile().then((f) => f.arrayBuffer());
    return new Uint8Array(buf);
  }

  async writeFile(path: string, data: Uint8Array): Promise<void> {
    const parts = safePath(path); const name = parts.pop()!;
    let dir = this.root;
    for (const part of parts) dir = await dir.getDirectoryHandle(part, { create: true });
    const w = await (await dir.getFileHandle(name, { create: true })).createWritable();
    try { await w.write(data.buffer as ArrayBuffer); await w.close(); } catch (e) { await w.abort().catch(() => {}); throw e; }
  }
}

import { HostDirectory, type HostFile } from "./hostDirectory.ts";
import { putGuestFile, shareReady } from "./guestFiles.ts";
import { normalizeGuestBundlePath } from "./guestBundle.ts";

export type HostShareMode = "host-persistent" | "ephemeral";
export interface SyncReport { copied: number; skipped: number; pending: number; errors: string[]; conflicts: string[] }
export interface HostShareBundle { name: string; files: Array<{ path: string; data: Uint8Array }> }

interface GuestFs { SearchPath(path: string): { id: number; parentid: number }; }
interface GuestEmulator { fs9p?: GuestFs; create_file(path: string, data: Uint8Array): Promise<unknown>; read_file?: (path: string) => Promise<Uint8Array>; }

export class HostShare {
  private readonly dirty = new Map<string, Uint8Array>();
  private readonly known = new Set<string>();
  private disposed = false;
  private readonly host: HostDirectory | null;
  constructor(host: HostDirectory | null) { this.host = host; }

  get mode(): HostShareMode { return this.host ? "host-persistent" : "ephemeral"; }
  rootName(): string | null { return this.host?.root.name ?? null; }

  async syncToGuest(emulator: unknown): Promise<SyncReport> {
    const report: SyncReport = { copied: 0, skipped: 0, pending: this.dirty.size, errors: [], conflicts: [] };
    if (!this.host) return report;
    if (!shareReady(emulator)) { report.errors.push("fs9p unavailable"); return report; }
    let files: HostFile[];
    try { files = await this.host.readTree(); } catch (e) { report.errors.push(String(e)); return report; }
    for (const file of files) {
      this.known.add(file.path);
      try { await putGuestFile(emulator, file.path, file.data); report.copied++; }
      catch (e) { report.errors.push(`${file.path}: ${String(e)}`); }
    }
    report.pending = this.dirty.size;
    return report;
  }

  markDirty(path: string, data: Uint8Array): void { if (!this.disposed) { this.dirty.set(path, Uint8Array.from(data)); this.known.add(path); } }

  async flushFromGuest(emulator: unknown): Promise<SyncReport> {
    const report: SyncReport = { copied: 0, skipped: 0, pending: this.dirty.size, errors: [], conflicts: [] };
    if (!this.host) return report;
    if (!emulator) { report.errors.push("emulator unavailable"); return report; }
    const guest = emulator as GuestEmulator;
    for (const [path, data] of this.dirty) {
      try { await this.host.writeFile(path, data); this.dirty.delete(path); report.copied++; }
      catch (e) { report.errors.push(`${path}: ${String(e)}`); }
    }
    report.pending = this.dirty.size;
    return report;
  }

  async installBundle(emulator: unknown, bundle: HostShareBundle): Promise<{ files: number; bytes: number }> {
    let bytes = 0;
    for (const file of bundle.files) {
      const path = normalizeGuestBundlePath(`apps/${bundle.name}`, file.path);
      await putGuestFile(emulator, path, file.data);
      this.markDirty(path, file.data);
      bytes += file.data.byteLength;
    }
    return { files: bundle.files.length, bytes };
  }

  dispose(): void { this.disposed = true; }
}

/**
 * Small, app-agnostic helpers for the browser-side v86 9P tree.
 *
 * This module is deliberately about files only.  It does not know about
 * recordings, KWS, or any other guest application.  Applications arrive as
 * bundles and use these primitives to materialise their files under /share.
 */

interface GuestFs {
  SearchPath(path: string): { id: number; parentid: number };
  CreateDirectory(name: string, parentid: number): number;
  Unlink(parentid: number, name: string): number;
  read_dir?(path: string): string[] | undefined;
}

interface GuestEmulator {
  fs9p?: GuestFs;
  create_file(path: string, data: Uint8Array): Promise<unknown>;
}

/** Whether the running emulator exposed its 9P filesystem. */
export function shareReady(emulator: unknown): boolean {
  return !!(emulator as GuestEmulator | null)?.fs9p;
}

/** Look up a path in the live guest tree; never cache this fact across VM restarts. */
export function shareFileExists(emulator: unknown, guestPath: string): boolean {
  const fs = (emulator as GuestEmulator | null)?.fs9p;
  if (!fs) return false;
  try {
    return fs.SearchPath(guestPath).id !== -1;
  } catch {
    return false;
  }
}

/** mkdir -p and write one path relative to the 9P root. */
export async function putGuestFile(
  emulator: unknown,
  guestPath: string,
  bytes: Uint8Array,
): Promise<void> {
  const emu = emulator as GuestEmulator | null;
  const fs = emu?.fs9p;
  if (!fs) throw new Error("fs9p 不可达(VM 没跑,或没带 filesystem 启动)");
  const parts = guestPath.split("/").filter(Boolean);
  if (parts.length === 0) throw new TypeError("guest file path is empty");
  let cur = "";
  for (let i = 0; i < parts.length - 1; i++) {
    cur = cur ? `${cur}/${parts[i]}` : parts[i];
    const info = fs.SearchPath(cur);
    if (info.id === -1) fs.CreateDirectory(parts[i], info.parentid);
  }
  await emu.create_file(guestPath, bytes);
}

/** Best-effort removal used to keep the guest view in sync with host storage. */
export function removeGuestFile(emulator: unknown, guestPath: string): void {
  const fs = (emulator as GuestEmulator | null)?.fs9p;
  if (!fs) return;
  try {
    const info = fs.SearchPath(guestPath);
    if (info.id !== -1) fs.Unlink(info.parentid, guestPath.split("/").pop()!);
  } catch {
    // Guest storage is ephemeral; a missing path is already in the desired state.
  }
}

/** Enumerate a directory when the v86 filesystem implementation supports it. */
export function listGuestFiles(emulator: unknown, directory: string): string[] {
  const fs = (emulator as GuestEmulator | null)?.fs9p;
  if (!fs?.read_dir) return [];
  try {
    return fs.read_dir(directory) ?? [];
  } catch {
    return [];
  }
}
import { putGuestFile } from "./guestFiles.ts";

export interface GuestBundleFile {
  path: string;
  data: Uint8Array;
  bytes?: number;
}

export interface GuestBundle {
  name: string;
  root?: string;
  files: GuestBundleFile[];
}

export type GuestBundleProgress = (path: string, completedBytes: number, totalBytes: number) => void;

function safeSegment(value: string): boolean {
  return value.length > 0 && value !== "." && value !== ".." && !value.includes("\\");
}

export function normalizeGuestBundlePath(root: string, path: string): string {
  if (path.startsWith("/") || root.startsWith("/")) throw new TypeError("guest bundle paths must be relative");
  const parts = [...root.split("/"), ...path.split("/")].filter(Boolean);
  if (!parts.length || parts.some((part) => !safeSegment(part))) throw new TypeError("unsafe guest bundle path");
  return parts.join("/");
}

export async function installGuestBundle(
  emulator: unknown,
  bundle: GuestBundle,
  options: { signal?: AbortSignal; onProgress?: GuestBundleProgress; persistFile?: (path: string, data: Uint8Array) => Promise<void> } = {},
): Promise<{ files: number; bytes: number; root: string }> {
  if (!bundle.name.trim()) throw new TypeError("guest bundle name is required");
  const root = bundle.root ?? `apps/${bundle.name}`;
  const paths = new Set<string>();
  let total = 0;
  for (const file of bundle.files) {
    const target = normalizeGuestBundlePath(root, file.path);
    if (paths.has(target)) throw new TypeError(`duplicate guest bundle path: ${target}`);
    paths.add(target);
    if (file.bytes !== undefined && file.bytes !== file.data.byteLength) {
      throw new Error(`${file.path} length mismatch: got ${file.data.byteLength}, expected ${file.bytes}`);
    }
    total += file.data.byteLength;
  }
  let completed = 0;
  for (const file of bundle.files) {
    if (options.signal?.aborted) throw new Error(`guest bundle ${bundle.name} installation aborted`);
    const target = normalizeGuestBundlePath(root, file.path);
    await putGuestFile(emulator, target, file.data);
    await options.persistFile?.(target, file.data);
    completed += file.data.byteLength;
    options.onProgress?.(target, completed, total);
  }
  return { files: bundle.files.length, bytes: completed, root };
}

/**
 * shareVault —— **用户自己电脑上的那个文件夹**,9p 共享盘的宿主。
 *
 * ## 为什么有这个模块
 *
