  }
}

// ── IndexedDB:句柄的持久化(一个库、一个 store、一个 key)──────────────────

function openDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, 1);
    req.onupgradeneeded = () => {
      if (!req.result.objectStoreNames.contains(DB_STORE)) req.result.createObjectStore(DB_STORE);
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error ?? new Error("indexedDB.open 失败"));
  });
}

function idbTx<T>(mode: IDBTransactionMode, run: (store: IDBObjectStore) => IDBRequest<T>): Promise<T> {
  return openDb().then(
    (db) =>
      new Promise<T>((resolve, reject) => {
        const tx = db.transaction(DB_STORE, mode);
        const req = run(tx.objectStore(DB_STORE));
        req.onsuccess = () => resolve(req.result);
        req.onerror = () => reject(req.error ?? new Error("IndexedDB 请求失败"));
        tx.oncomplete = () => db.close();
      }),
  );
}

/** 读回上次选的文件夹句柄(没有/读不出都返回 null,不抛)。 */
export async function loadSavedRoot(): Promise<FileSystemDirectoryHandle | null> {
  if (!fsaSupported()) return null;
  try {
    const h = await idbTx<unknown>("readonly", (s) => s.get(DB_KEY) as IDBRequest<unknown>);
    // 存进去的是句柄本体;库被别的东西污染过就当没有
    return h && typeof (h as FileSystemHandle).kind === "string" && (h as FileSystemHandle).kind === "directory"
      ? (h as FileSystemDirectoryHandle)
      : null;
  } catch {
    return null;
  }
}

async function saveRoot(handle: FileSystemDirectoryHandle): Promise<void> {
  await idbTx("readwrite", (s) => s.put(handle, DB_KEY) as IDBRequest<IDBValidKey>);
}

/** 忘掉当前文件夹(用户主动"换一个"或句柄已失效时)。 */
export async function forgetSavedRoot(): Promise<void> {
  try {
    await idbTx("readwrite", (s) => s.delete(DB_KEY) as IDBRequest<undefined>);
  } catch {
    /* 忘不掉也不该拦住用户重选:重选会覆盖同一个 key */
  }
}

// ── 选择与授权 ─────────────────────────────────────────────────────────────

/**
 * 弹目录选择器并记住选中的文件夹。**必须在用户手势里调**。
 * 用户按 Esc 取消时浏览器抛 AbortError —— 这里原样往上抛,由 UI 区分
 * "用户取消"(不报错)与"真失败"(报错)。
 */
export async function pickShareRoot(): Promise<FileSystemDirectoryHandle> {
  if (!window.showDirectoryPicker) throw new Error("这个浏览器没有 showDirectoryPicker(需要 Chromium 系 + https/localhost)");
  const handle = await window.showDirectoryPicker({ id: PICKER_ID, mode: "readwrite" });
  await saveRoot(handle);
  return handle;
}

/** 用户是不是按了取消(而不是出了错)。 */
export function isAbort(e: unknown): boolean {
  return e instanceof DOMException && (e.name === "AbortError" || e.name === "NotAllowedError" && e.message === "");
}

/**
 * 查当前授权状态,不弹窗。
 *
 * 句柄上**没有** queryPermission 方法时按 "granted" 处理:这个方法只长在
 * 需要用户授权的句柄上(picker 拿到的),不长在本来就不受权限管的句柄上
 * (OPFS)。把"没有权限门"读成"待授权"会永远卡在恢复按钮上,读成"已授权"
 * 才是它的真实语义 —— 真拿不到权限的句柄下一步写入会明确抛错,不会静默。
 */
export async function queryRootPermission(handle: FileSystemDirectoryHandle): Promise<VaultPermission> {
  if (!handle.queryPermission) return "granted";
  try {
    return (await handle.queryPermission({ mode: "readwrite" })) as VaultPermission;
  } catch {
    return "prompt";
  }
}

/** 请求授权(会弹窗)。**必须在用户手势里调**,否则 Chromium 直接判 denied。 */
export async function requestRootPermission(handle: FileSystemDirectoryHandle): Promise<VaultPermission> {
  if (!handle.requestPermission) return "granted";
  try {
    return (await handle.requestPermission({ mode: "readwrite" })) as VaultPermission;
  } catch {
    return "denied";
  }
}

// ── 文件夹里的读写(全部相对"用户选的那一级")────────────────────────────

/** 拿子目录句柄。create=true 时不存在就建(第一次写录音会走到)。 */
async function subdir(
  root: FileSystemDirectoryHandle,
  name: string,
  create: boolean,
): Promise<FileSystemDirectoryHandle | null> {
  try {
    return await root.getDirectoryHandle(name, { create });
  } catch (e) {
    if (e instanceof DOMException && e.name === "NotFoundError") return null;
    throw e;
  }
}

/** 目录里一条文件的原始信息(不解释内容;WAV 头交给调用方读)。 */
export interface VaultFile {
  name: string;
  bytes: number;
  /** 文件的 lastModified(毫秒)。 */
  mtime: number;
  /** 头部若干字节,给调用方解析格式用(不足则更短)。 */
  head: Uint8Array;
}

/** 读头部时最多取多少字节 —— 够覆盖 RIFF + fmt + data 三个块头。 */
const HEAD_BYTES = 4096;

/**
 * 列出 `<root>/<sub>/` 里名字过 nameRe 的文件,连头部一起取回。
 * 子目录不存在 = 还没存过东西,返回空数组(不是错误)。
 */
export async function listVaultFiles(
  root: FileSystemDirectoryHandle,
  sub: string,
  nameRe: RegExp,
): Promise<VaultFile[]> {
  const dir = await subdir(root, sub, false);
  if (!dir) return [];
  const out: VaultFile[] = [];
  for await (const [name, handle] of dir.entries()) {
    if (handle.kind !== "file" || !nameRe.test(name)) continue;
    try {
      const file = await (handle as FileSystemFileHandle).getFile();
      const head = new Uint8Array(await file.slice(0, Math.min(HEAD_BYTES, file.size)).arrayBuffer());
      out.push({ name, bytes: file.size, mtime: file.lastModified, head });
    } catch {
      /* 单条读不出来不该拖垮整个列表 —— 少列一条,不谎报 */
    }
  }
  return out;
}

export async function readVaultFile(
  root: FileSystemDirectoryHandle,
  sub: string,
  name: string,
): Promise<Uint8Array> {
  const dir = await subdir(root, sub, false);
  if (!dir) throw new Error(`文件夹里没有 ${sub}/`);
  const file = await (await dir.getFileHandle(name)).getFile();
  return new Uint8Array(await file.arrayBuffer());
}

/** 写(覆盖)。子目录不存在就建。写完 close 才算落盘 —— 中途抛错等于没写。 */
export async function writeVaultFile(
  root: FileSystemDirectoryHandle,
  sub: string,
  name: string,
  bytes: Uint8Array,
): Promise<void> {
  const dir = await root.getDirectoryHandle(sub, { create: true });
  const fh = await dir.getFileHandle(name, { create: true });
  const w = await fh.createWritable();
  try {
    await w.write(bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) as ArrayBuffer);
  } catch (e) {
    await w.abort().catch(() => {});
    throw e;
  }
  await w.close();
}

/** 删一个文件。不存在按删掉了算(幂等)。 */
export async function removeVaultFile(
  root: FileSystemDirectoryHandle,
  sub: string,
  name: string,
): Promise<void> {
  const dir = await subdir(root, sub, false);
  if (!dir) return;
  try {
    await dir.removeEntry(name);
  } catch (e) {
    if (e instanceof DOMException && e.name === "NotFoundError") return;
    throw e;
  }
}

/**
 * 句柄是不是已经失效(文件夹被删/被移走/被改名)。
 *
 * FSA 没有"这个句柄还活着吗"的直接问法,只能试着用一下:对根做一次
 * getDirectoryHandle(create:false) 之外还要能列举 —— 单纯 queryPermission
 * 返回 granted **不代表目录还在**(这是量具陷阱:权限记录活着,目录可以已经没了)。
 */
export async function rootAlive(root: FileSystemDirectoryHandle): Promise<boolean> {
  try {
    // 只取迭代器的第一步:目录没了会在这里抛 NotFoundError
    await root.entries().next();
    return true;
  } catch {
    return false;
  }
}

/**
 * shareBridge — **guest 往 9p 里写的东西,搬进用户自己选的文件夹**(方案 A:写回钩子)。
 *
 * 方向要先说清楚,这个仓里有两条相反的链路,混起来会看不懂:
 *
 *   浏览器写(@/audio/recordingsStore 的 fsaBackend)
 *       页面拿到样本 → 编码 WAV → 直接写 FSA,顺手也塞一份进 fs9p。
 *       数据从来没经过 guest。
 *   **guest 写(本文件)**
 *       guest 里 `echo > /share/x` → 内核经 9p → v86 的内存 inode → 本文件搬进
 *       用户目录。这是反方向,上面那条一个字节都覆盖不到。
 *
 * ## 为什么是"写回 + 最终一致",不是直通
 *
 * v86 的 `FileStorageInterface` 是**内容寻址且只读**的(read/cache/uncache,没有
 * 路径、没有目录、没有删除),而 `SearchPath`/`Unlink`/`read_dir` 这些又全是
 * **同步**函数、`lib/9p.js` 的分发依赖它们同步返回 —— File System Access API
 * 则全是 async。要真直通就得把 9p 的整条 dispatch 改成 async(docs 里的方案 B),
 * 改动面覆盖 filesystem.js 大半。方案 A 不碰同步语义:v86 的内存 inode 树仍是
 * 权威视图,我们只在它变化之后**异步搬一份**出去。
 *
 * 代价是明写在文档里的:**最终一致,不是实时**。
 *
 * ## 触发点:v86 自己的 NotifyListeners
 *
 * `FS.prototype.NotifyListeners(id, action, info)` 在 vendor 里本来就是个空存根,
 * 五个调用点(newdir / newfile / write / delete / rename)一个不少。我们在运行时
 * **包一层**(链式调用原实现,detach 时原样还回去),不需要新增调用点。
 *
 * 唯一动过 vendor 的地方:`write` 的通知原本在 `Write()` **入口**发,那时
 * `set_data()` 还没跑,听到事件去读文件读到的是**上一版**。补丁把它挪到数据落地
 * 之后(patches/hooks/,1 个调用点搬家,0 个新增)。
 *
 * ## 事件只说"变了",不说"哪儿变了"
 *
 * 事件只带 inode id;而 `GetFullPath()` / `GetParent()` 都 `dbg_assert(IsDirectory)`
 * —— **文件 inode 根本反查不出路径**。所以这里不做 id→路径的账,改成:收到任何
 * 事件就防抖,然后对 9p 树做一次**对账遍历**(read_dir 是同步且按路径的,遍历很便宜)。
 * 好处是创建/写入/改名/漏掉的事件都由同一条路径收敛,不依赖事件的完整性。
 *
 * ## 不做的事(护栏做在机制层,不靠调用方自觉)
 *
 * **不传播删除,也不传播改名的"旧名消失"那一半。** 理由是可证伪的事故场景:
 * fs9p 活在浏览器内存里,页面一刷新/VM 一重启就是空的。若"9p 里没有 = 用户目录里删掉",
 * 那么开一次新页面就会把用户文件夹里的东西全删光。宁可留下孤儿文件,不许删用户的东西。
 * 哪些操作不会同步,原样写在 docs/client-side-storage.md 里。
 */

/** v86 的 fs9p 上我们用到的那几个方法(全部同步,除了 read_file)。 */
interface Fs9pTree {
  SearchPath(path: string): { id: number; parentid: number };
  IsDirectory(idx: number): boolean;
  read_dir(path: string): string[] | undefined;
  read_file(path: string): Promise<Uint8Array | null>;
  NotifyListeners(id: number, action: string, info?: unknown): void;
}

interface EmulatorWithFs {
  fs9p?: Fs9pTree;
}

/** 写回的实况。UI 原样显示 —— 宁可显示"取不到",不许显示猜的值。 */
export interface WritebackStats {
  /** 对账跑了几轮。 */
  reconciles: number;
  /** 真正写出去过的文件数(内容没变的不算)。 */
  filesWritten: number;
  bytesWritten: number;
  /** 最近一次对账的时刻(epoch ms);null = 还没跑过。 */
  lastAt: number | null;
  /** 最近一次失败的人话;null = 没失败过。 */
  lastError: string | null;
}

export const emptyWritebackStats: WritebackStats = {
  reconciles: 0, filesWritten: 0, bytesWritten: 0, lastAt: null, lastError: null,
};

const msg = (e: unknown) => (e instanceof Error ? e.message : String(e));

/** FNV-1a 32 位。只用来回答"这个文件跟我上次搬的那份一样吗"。 */
function digest(bytes: Uint8Array): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < bytes.length; i++) {
    h ^= bytes[i];
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return `${bytes.length}:${h.toString(16)}`;
}

function sameBytes(a: Uint8Array, b: Uint8Array): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
  return true;
}

/** 顺着相对路径拿到目录句柄(按需创建)。 */
async function dirFor(
  root: FileSystemDirectoryHandle,
  segments: string[],
): Promise<FileSystemDirectoryHandle> {
  let cur = root;
  for (const seg of segments) cur = await cur.getDirectoryHandle(seg, { create: true });
  return cur;
}

/**
 * 把 9p 树里的一个文件搬进用户目录。
 * 返回真的写了多少字节;内容与目标一致时返回 0(不重写,也不动 mtime)。
 */
async function mirrorFile(
  root: FileSystemDirectoryHandle,
  path: string,
  bytes: Uint8Array,
): Promise<number> {
  const parts = path.split("/").filter(Boolean);
  const name = parts.pop()!;
  const dir = await dirFor(root, parts);

  // 目标已经一模一样就别写:重灌(VM 一起来把用户目录里的录音回灌进 fs9p)
  // 会让每个文件都过一遍这里,白写一遍还会把 mtime 全刷新。
  try {
    const existing = new Uint8Array(await (await (await dir.getFileHandle(name)).getFile()).arrayBuffer());
    if (sameBytes(existing, bytes)) return 0;
  } catch { /* 不存在 / 读不了 —— 当作要写 */ }

  const fh = await dir.getFileHandle(name, { create: true });
  const w = await fh.createWritable();
  try {
    await w.write(bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) as ArrayBuffer);
  } catch (e) {
    await w.abort().catch(() => {});
    throw e;
  }
  await w.close();
  return bytes.length;
}

export interface AttachOptions {
  /** 现取现用 —— VM 可能还没起来,也可能被换掉。 */
  getEmulator: () => unknown;
  /** 当前用户目录;null = 没选/没授权,此时写回整个歇着。 */
  getRoot: () => FileSystemDirectoryHandle | null;
  /** 每轮对账之后回报实况(给 UI 显示)。 */
  onStats?: (s: WritebackStats) => void;
  /** 防抖:9p 是分块写的,一次 `cp` 会连着来很多次 write 事件。 */
  debounceMs?: number;
}

/**
 * 挂上写回钩子。返回 detach —— 会把 NotifyListeners 原样还回去。
 * fs9p 还不存在(VM 没起)时返回一个空 detach,调用方 VM 就绪后重挂即可。
 */
export function attachShareWriteback(opts: AttachOptions): () => void {
  const { getEmulator, getRoot, onStats, debounceMs = 250 } = opts;
  const maybeFs = (getEmulator() as EmulatorWithFs | null)?.fs9p;
  if (!maybeFs || typeof maybeFs.NotifyListeners !== "function") return () => {};
  // 收窄一次:下面的闭包(walk/reconcile)里再靠控制流推断,TS 会把它放回 undefined。
  const fs: Fs9pTree = maybeFs;

  const original = fs.NotifyListeners;
  const stats: WritebackStats = { ...emptyWritebackStats };
  /** 路径 → 上次搬出去的那份内容的指纹。只增不减(不传播删除)。 */
  const shadow = new Map<string, string>();

  let detached = false;
  let timer: ReturnType<typeof setTimeout> | null = null;
  let running = false;
  let again = false;

  /** 把 9p 树整个走一遍,变了的搬出去。 */
  async function reconcile(): Promise<void> {
    const root = getRoot();
    if (!root) return;                       // 没选文件夹 —— 什么都不做

    // 遍历本身是同步的(read_dir/SearchPath/IsDirectory 都同步),先把清单收齐,
    // 再去做异步的写 —— 免得边遍历边 await,树在中途被 guest 改掉。
    const files: string[] = [];
    const walk = (dir: string) => {
      const names = fs.read_dir(dir);
      if (!names) return;
      for (const name of names) {
        const p = dir ? `${dir}/${name}` : name;
        const info = fs.SearchPath(p);
        if (!info || info.id === -1) continue;
        if (fs.IsDirectory(info.id)) walk(p);
        else files.push(p);
      }
    };
    try {
      walk("");
    } catch (e) {
      stats.lastError = `遍历 9p 树失败:${msg(e)}`;
      return;
    }

    for (const p of files) {
      if (detached) return;
      try {
        const raw = await fs.read_file(p);
        const bytes = raw ?? new Uint8Array(0);
        const d = digest(bytes);
        if (shadow.get(p) === d) continue;   // 跟上次搬的那份一样,跳过
        const written = await mirrorFile(root, p, bytes);
        shadow.set(p, d);
        if (written > 0) {
          stats.filesWritten++;
          stats.bytesWritten += written;
        }
      } catch (e) {
        // 单个文件失败不该拖垮整轮:如实记下来,别静默。
        stats.lastError = `写回 ${p} 失败:${msg(e)}`;
      }
    }

    stats.reconciles++;
    stats.lastAt = Date.now();
    onStats?.({ ...stats });
  }

  /** 串行化:一轮没跑完就再来事件,记一笔,跑完再补一轮。 */
  async function runReconcile(): Promise<void> {
    if (running) { again = true; return; }
    running = true;
    try {
      do {
        again = false;
        await reconcile();
      } while (again && !detached);
    } finally {
      running = false;
    }
  }

  function schedule(): void {
    if (detached) return;
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => { timer = null; void runReconcile(); }, debounceMs);
  }

  // 链式包一层:原实现照调(v86 未来真往里写东西也不会被我们吃掉)。
  fs.NotifyListeners = function (this: unknown, id: number, action: string, info?: unknown) {
    try { original.call(this, id, action, info); } catch { /* 原实现是空存根,防御性 */ }
    schedule();
  };

  // 挂上就先对一次账:VM 起来之前 guest 可能已经写过东西了。
  schedule();

  return () => {
    detached = true;
    if (timer) { clearTimeout(timer); timer = null; }
    fs.NotifyListeners = original;
  };
}

