import { useEffect, useRef, useState } from "react";
import { shareReady } from "@/audio/recordingsStore";
import { attachShareWriteback, emptyWritebackStats, type WritebackStats } from "@/fs/shareBridge";
import type { ShareVaultState } from "@/ui/lab/useShareVault";

/** fs9p 就绪探测的上限,与 useRecordings 同量级(冷启动含 wasm 下载)。 */
const FS9P_WAIT_MS = 180_000;
const POLL_MS = 300;

export function useShareWriteback({
  running,
  getEmulator,
  vault,
}: {
  running: boolean;
  getEmulator: () => unknown;
  vault: ShareVaultState;
}): WritebackStats {
  const [stats, setStats] = useState<WritebackStats>(emptyWritebackStats);

  // 长流程里现取现用,不吃过期闭包(useRecordings 同款)。
  const getEmulatorRef = useRef(getEmulator);
  getEmulatorRef.current = getEmulator;

  // 真正能写的那个句柄:没授权的句柄等于没有,不许拿来冒充。
  const root = vault.permission === "granted" ? vault.root : null;
  const rootRef = useRef(root);
  rootRef.current = root;

  useEffect(() => {
    if (!running) { setStats(emptyWritebackStats); return; }

    let cancelled = false;
    let detach: (() => void) | null = null;

    void (async () => {
      const deadline = Date.now() + FS9P_WAIT_MS;
      while (!cancelled && Date.now() < deadline) {
        if (shareReady(getEmulatorRef.current())) {
          if (cancelled) return;
          detach = attachShareWriteback({
            getEmulator: () => getEmulatorRef.current(),
            getRoot: () => rootRef.current,
            onStats: (s) => { if (!cancelled) setStats(s); },
          });
          return;
        }
        await new Promise((r) => setTimeout(r, POLL_MS));
      }
    })();

    return () => {
      cancelled = true;
      detach?.();
    };
    // root/permission 变了要重挂:影子账是按目录记的,换目录必须重搬一遍。
  }, [running, root]);

  return stats;
}

