#include <nuttx/config.h>
#include <stdint.h>
#include <stdbool.h>
#include <syslog.h>
#include <debug.h>
#include <nuttx/arch.h>

#include "t113_usb.h"

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static inline uint32_t getreg32(uintptr_t addr)
{
  return *(volatile uint32_t *)addr;
}

static inline void putreg32(uint32_t val, uintptr_t addr)
{
  *(volatile uint32_t *)addr = val;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: t113_usb_clock_enable
 *
 * Description:
 *   Enable USB clock and deassert reset for specified port.
 *
 * Input Parameters:
 *   port - USB port number (0 or 1)
 *
 ****************************************************************************/

void t113_usb_clock_enable(int port)
{
  uint32_t regval;
  uintptr_t clk_reg;
  uint32_t gating_bit;
  uint32_t rst_bit;

  /* Select registers based on port */

  if (port == 0)
    {
      clk_reg = T113_CCU_USB0_CLK_REG;
      gating_bit = USB_BGR_USB0_GATING;
      rst_bit = USB_BGR_USB0_RST;
    }
  else
    {
      clk_reg = T113_CCU_USB1_CLK_REG;
      gating_bit = USB_BGR_USB1_GATING;
      rst_bit = USB_BGR_USB1_RST;
    }

  /* Enable bus clock gating */

  regval = getreg32(T113_CCU_USB_BGR_REG);
  regval |= gating_bit;
  putreg32(regval, T113_CCU_USB_BGR_REG);

  /* Deassert reset */

  regval = getreg32(T113_CCU_USB_BGR_REG);
  regval |= rst_bit;
  putreg32(regval, T113_CCU_USB_BGR_REG);

  /* Enable PHY clock and deassert PHY reset */

  regval = getreg32(clk_reg);
  regval |= USB_CLK_SCLK_GATING;
  regval |= USB_CLK_PHY_RST;
  /* OHCI 12M clock source (bits 25:24, mainline ccu-sun20i-d1 truth):
   * 0=pll-periph0/prediv, 1=hosc(24M)/2, 2=losc.  OHCI requires 12 MHz;
   * the old mux=0 with the "24MHz" comment fed double-rate clocking and
   * full-speed devices read back as LSDA=1 / CC=5 DeviceNotResponding.
   */

  regval &= ~USB_CLK_OHCI_CLK_SEL_MASK;
  regval |= USB_CLK_OHCI_CLK_SEL_12M;  /* hosc/2 = 12 MHz */
  putreg32(regval, clk_reg);

  /* Wait for clock to stabilize */

  up_udelay(100);

  /* Enable AHB master burst and UTMI/ULPI bridge ("passby").
   * The PMU_IRQ_ENABLE register lives at USB_BASE + 0x800 for each port.
   * Without this the EHCI AHB DMA master cannot issue burst transactions.
   * Mirrors Linux sunxi-hci.c usb_passby() / SUNXI_USB_PMU_IRQ_ENABLE.
   * Value 0x0701 = INCR8(bit10) | INCR4(bit9) | INCRX_ALIGN(bit8) | ULPI_BYPASS(bit0).
   * Verified against U-Boot ehci-sunxi.c which performed this before EHCI init
   * and successfully enumerated USB1 on this board.
   */

  {
    uintptr_t pmu_reg;
    uint32_t pmu_val;

    if (port == 0)
      {
        pmu_reg = T113_USB0_BASE + USB_PMU_IRQ_ENABLE_OFFSET;
      }
    else
      {
        pmu_reg = T113_USB1_BASE + USB_PMU_IRQ_ENABLE_OFFSET;
      }

    pmu_val  = getreg32(pmu_reg);
    pmu_val |= USB_PMU_AHB_INCR8 | USB_PMU_AHB_INCR4 |
               USB_PMU_AHB_INCRX_ALIGN | USB_PMU_ULPI_BYPASS;
    putreg32(pmu_val, pmu_reg);
  }

  uinfo("USBCLK port%d BGR=%08lx CLK_REG=%08lx\n", port,
        (unsigned long)getreg32(T113_CCU_USB_BGR_REG),
        (unsigned long)getreg32(clk_reg));
}

/****************************************************************************
 * Name: t113_usb_clock_disable
 *
 * Description:
 *   Disable USB clock and assert reset for specified port.
 *
 * Input Parameters:
 *   port - USB port number (0 or 1)
 *
 ****************************************************************************/

void t113_usb_clock_disable(int port)
{
  uint32_t regval;
  uintptr_t clk_reg;
  uint32_t gating_bit;
  uint32_t rst_bit;

  /* Select registers based on port */

  if (port == 0)
    {
      clk_reg = T113_CCU_USB0_CLK_REG;
      gating_bit = USB_BGR_USB0_GATING;
      rst_bit = USB_BGR_USB0_RST;
    }
  else
    {
      clk_reg = T113_CCU_USB1_CLK_REG;
      gating_bit = USB_BGR_USB1_GATING;
      rst_bit = USB_BGR_USB1_RST;
    }

  /* Disable PHY clock and assert PHY reset */

  regval = getreg32(clk_reg);
  regval &= ~USB_CLK_SCLK_GATING;
  regval &= ~USB_CLK_PHY_RST;
  putreg32(regval, clk_reg);

  /* Assert reset */

  regval = getreg32(T113_CCU_USB_BGR_REG);
  regval &= ~rst_bit;
  putreg32(regval, T113_CCU_USB_BGR_REG);

  /* Disable bus clock gating */

  regval = getreg32(T113_CCU_USB_BGR_REG);
  regval &= ~gating_bit;
  putreg32(regval, T113_CCU_USB_BGR_REG);
}

/****************************************************************************
 * Name: t113_usb_phy_init
 *
 * Description:
 *   Initialize USB PHY for specified port and mode.
 *
 * Input Parameters:
 *   port      - USB port number (0 or 1)
 *   host_mode - true for host mode, false for device mode
 *
 ****************************************************************************/

void t113_usb_phy_init(int port, bool host_mode)
{
  /* Validate port number */

  if (port < 0 || port > 1)
    {
      return;
    }

  /* USB1 (host-only): power up its PHY.  Mainline phy-sun4i-usb
   * (sun20i_d1_cfg: hci_phy_ctl_clear = PHY_CTL_SIDDQ) clears SIDDQ in
   * the PMU HCI_PHY_CTL register for EVERY HCI phy; without it the
   * analog PHY stays powered down and full-speed devices misread as
   * low-speed with CC=5 DeviceNotResponding on EP0.
   */

  if (port == 1)
    {
      uintptr_t pmu_phyctl = T113_USB1_BASE + USB_PMU_IRQ_ENABLE_OFFSET +
                             USB_HCI_PHY_CTL_OFFSET;
      uint32_t  v;

      v  = getreg32(pmu_phyctl);
      v &= ~USB_HCI_PHY_CTL_SIDDQ;
      putreg32(v, pmu_phyctl);

      uinfo("USB1 PHY: SIDDQ cleared (HCI_PHY_CTL=%08lx)\n",
            (unsigned long)getreg32(pmu_phyctl));
      return;
    }

  /* USB0 has OTG PHY / ISCR control. */

  if (port == 0)
    {
      uint32_t regval;
      uintptr_t iscr = T113_USB0_BASE + USB_ISCR_OFFSET;

      /* Configure MUSB ISCR (Interface Status and Control Register).
       *
       * For device mode: force ID=B-device (peripheral), VBUS always valid.
       * This tells the OTG state machine we are a USB device so it won't
       * try to drive VBUS.
       *
       * FORCE_ID   bits[15:14]: 0x2 = force ID to B-device (peripheral)
       * FORCE_VBUS bits[13:12]: 0x3 = VBUS always valid (board has no GPIO)
       * DPDM_PULLUP_EN bit[16]: keep D+ pullup enabled via PHY
       * ID_PULLUP_EN   bit[17]: enable ID pin pullup for B-device detection
       *
       * In host mode: force ID=A-device (host), normal VBUS detection.
       */

      regval = getreg32(iscr);

      /* Clear the writable force/source/pullup fields + change-detect first.
       * VBUS_VALID_SRC = bits[11:10], FORCE_VBUS_VALID = bits[13:12],
       * FORCE_ID = bits[15:14], DPDM/ID pullup-en = bits[17:16].
       */

      regval &= ~((0x3u << 10) | (0x3u << 12) | (0x3u << 14) |
                  (0x1u << 16) | (0x1u << 17));

      /* Clear the W1C change-detect bits so we don't accidentally re-trigger. */

      regval &= ~((0x1u << 6) | (0x1u << 5) | (0x1u << 4));

      if (host_mode)
        {
          regval |= (0x1u << 14);  /* FORCE_ID = A-device (host) */
        }
      else
        {
          /* Match the LINUX golden config (devmem readback on this board
           * while g_serial was enumerated and passing data, 2026-06-10:
           * ISCR=0x4303F000): ID_PULLUP_EN + DPDM_PULLUP_EN + FORCE_ID=3
           * + FORCE_VBUS_VALID=3, and VBUS_VALID_SRC=0.
           *
           * Supersedes the earlier BROM-derived value (VBUS_VALID_SRC=3,
           * pullup-en clear): the "bits 16/17 break connect" observation
           * dates from before the PHY routing fix and was confounded by
           * VBUS_VALID_SRC=3.  Linux demonstrably works with this exact
           * combination on this silicon.
           */

          regval |= (0x3u << 12);  /* FORCE_VBUS_VALID = always valid */
          regval |= (0x3u << 14);  /* FORCE_ID = B-device */
          regval |= (0x1u << 16);  /* DPDM_PULLUP_EN */
          regval |= (0x1u << 17);  /* ID_PULLUP_EN */
        }

      putreg32(regval, iscr);

      /* Power up the USB2.0 PHY and route PHY0 to the right controller.
       * (sun20i-d1/T113 PHY, per mainline phy-sun4i-usb.c sun20i_d1_cfg:
       *  siddq_in_base + phy0_dual_route.)  Without this the PHY stays in
       * SIDDQ power-down and PHY0 D+/D- never reaches the MUSB device
       * controller, so SOFTCONN has no effect and the host sees nothing.
       */

      {
        uintptr_t pmu_phyctl = T113_USB0_BASE + USB0_PMU0_OFFSET +
                               USB_HCI_PHY_CTL_OFFSET;
        uintptr_t phyctl_a33 = T113_USB0_BASE + USB0_PHYCTL_A33_OFFSET;
        uintptr_t otgctl     = T113_USB0_BASE + USB0_PHY_OTGCTL_OFFSET;
        uint32_t  v;

        /* 1. Clear SIDDQ in the PMU HCI_PHY_CTL register (power up). */

        v  = getreg32(pmu_phyctl);
        v &= ~USB_HCI_PHY_CTL_SIDDQ;
        putreg32(v, pmu_phyctl);

        /* 2. PHYCTL_A33: clear SIDDQ (power up) and, for device mode, force
         *    VBUS valid (board has no VBUS sense line).
         */

        v  = getreg32(phyctl_a33);
        v &= ~USB_PHYCTL_A33_SIDDQ;
        if (!host_mode)
          {
            v |= USB_PHYCTL_A33_VBUSVLDEXT;
          }

        putreg32(v, phyctl_a33);

        /* 3. Route PHY0: to MUSB for device mode, to HCI for host mode. */

        v = getreg32(otgctl);
        if (host_mode)
          {
            v &= ~USB_OTGCTL_ROUTE_MUSB;
          }
        else
          {
            v |= USB_OTGCTL_ROUTE_MUSB;
          }

        putreg32(v, otgctl);
      }

      /* NOTE: do NOT touch SUNXI_SRAMC_BASE+0x04 — the BROM leaves it 0 while
       * the gadget enumerates (read back over FEL), so the T113 MUSB does not
       * need the older-sunxi "8KB FIFO" SRAM remap.  Setting it broke nothing
       * observable but does not match the golden config, so it is omitted.
       */
    }

  /* USB1 is always host mode, no special PHY configuration needed */
}

