static void clock_set_pll_cpu(u32 clk)
{
	u32 n, k, m, p, rval;

	if (clk > 720000000)
		clk = 720000000;

	if ((clk % 24000000) == 0) {
		n = clk / 24000000;
		k = 1;
		m = 1;
		p = 0;
	} else if ((clk % 12000000) == 0) {
		n = clk / 12000000;
		k = 2;
		m = 1;
		p = 0;
	} else {
		n = clk / 24000000;
		k = 1;
		m = 1;
		p = 0;
	}

	rval = read32(F1C_CCU_BASE + CCU_PLL_CPU_CTRL);
	rval &= ~((0x3 << 16) | (0x1f << 8) | (0x3 << 4) | (0x3 << 0));
	rval |= (1U << 31) | (p << 16) | (n << 8) | (k << 4) | m;
	write32(F1C_CCU_BASE + CCU_PLL_CPU_CTRL, rval);
	sunxi_clk_wait_pll_lock(F1C_CCU_BASE + CCU_PLL_CPU_CTRL, 0xfff);
}

void sunxi_clk_init(void)
{
	u32 val;

	write32(F1C_CCU_BASE + CCU_PLL_STABLE_TIME0, 0x1ff);
	write32(F1C_CCU_BASE + CCU_PLL_STABLE_TIME1, 0x1ff);

	val = read32(F1C_CCU_BASE + CCU_CPU_CFG);
	val &= ~(0x3 << 16);
	val |= (0x1 << 16);
	write32(F1C_CCU_BASE + CCU_CPU_CFG, val);
	sdelay(100);

	write32(F1C_CCU_BASE + CCU_PLL_VIDEO_CTRL, F1C_PLL_VIDEO_CONFIG);
	sdelay(100);
	write32(F1C_CCU_BASE + CCU_PLL_PERIPH_CTRL, F1C_PLL_PERIPH_CONFIG);
	sdelay(100);
	write32(F1C_CCU_BASE + CCU_AHB_APB_CFG, F1C_AHB_APB_CLK_CONFIG);
	sdelay(100);

	val = read32(F1C_CCU_BASE + CCU_DRAM_CLK_GATE);
	val |= (0x1 << 26) | (0x1 << 24) | (0x1 << 3) | (0x1 << 2) | (0x1 << 1) | (0x1 << 0);
	write32(F1C_CCU_BASE + CCU_DRAM_CLK_GATE, val);
	sdelay(100);

	clock_set_pll_cpu(408000000);
	val = read32(F1C_CCU_BASE + CCU_CPU_CFG);
	val &= ~(0x3 << 16);
	val |= (0x2 << 16);
	write32(F1C_CCU_BASE + CCU_CPU_CFG, val);
	sdelay(100);
}

/* Get PLL_PERIPH rate - F1C PLL_PERIPH is typically 600MHz */
uint32_t sunxi_clk_get_peri1x_rate(void)
{
	u32 reg32 = read32(F1C_CCU_BASE + CCU_PLL_PERIPH_CTRL);
	if (reg32 & (1 << 31)) {
		u32 n = ((reg32 >> 8) & 0x1f) + 1;
		u32 k = ((reg32 >> 4) & 0x3) + 1;
		return 24000000 * n * k;
	}
	return 0;
}

/* Get APB clock rate - F1C APB is derived from AHB */
uint32_t sunxi_clk_get_apb_rate(void)
{
	/* F1C100S: APB = PLL_PERIPH / (ahb_pre_div × apb_div) = 600MHz / (3 × 2) = 100MHz */
	u32 cfg_reg = read32(F1C_CCU_BASE + CCU_AHB_APB_CFG);
	u32 pll_periph = sunxi_clk_get_peri1x_rate();

	return sunxi_clk_calc_apb_rate_legacy(pll_periph, cfg_reg);
}

