// SPDX-License-Identifier: GPL-2.0+
/*
 * Allwinner Clock Common Functions
 * Shared code for V3S/H3/F1C clock initialization
 */

#include <stdint.h>
#include "main.h"
#include "io.h"
#include "sunxi_clk_common.h"

/**
 * sunxi_clk_wait_pll_lock - Wait for PLL lock with timeout
 * @reg_addr: PLL control register address
 * @timeout: Timeout in loop iterations (0 = wait forever)
 *
 * Return: 0 on success, -1 on timeout
 */
int sunxi_clk_wait_pll_lock(uint32_t reg_addr, int timeout)
{
	uint32_t rval;
	int time = timeout;

	if (timeout == 0) {
		/* Wait forever */
		while (!(read32(reg_addr) & (1 << 28)))
			;
		return 0;
	}

	/* Wait with timeout */
	do {
		rval = read32(reg_addr);
		time--;
	} while (time && !(rval & (1 << 28)));

	return (time == 0) ? -1 : 0;
}

