/**
 * sunxi_clk_set_pll_cpux_sun8i - Set CPU PLL for Sun8i SoCs (V3S/H3)
 * @ccu_base: CCU base address
 * @reg_axi_cfg: CPU/AXI configuration register offset
 * @reg_pll_ctrl: PLL CPU control register offset
 * @clk: Target CPU clock frequency in Hz
 *
 * Shared CPU PLL configuration for V3S and H3.
 */
void sunxi_clk_set_pll_cpux_sun8i(uint32_t ccu_base, uint32_t reg_axi_cfg,
                                   uint32_t reg_pll_ctrl, uint32_t clk)
{
	int p = 0;
	int k = 1;
	int m = 1;
	uint32_t val;

	/* Calculate PLL parameters based on target frequency */
	if (clk > 1152000000)
		k = 2;
	else if (clk > 768000000) {
		k = 3;
		m = 2;
	}

	/* Switch to 24MHz clock while changing cpu pll */
	val = (2 << 0) | (1 << 8) | (1 << 16);
	write32(ccu_base + reg_axi_cfg, val);

	/* cpu pll rate = ((24000000 * n * k) >> p) / m */
	val = (0x1 << 31);
	val |= ((p & 0x3) << 16);
	val |= ((((clk / (24000000 * k / m)) - 1) & 0x1f) << 8);
	val |= (((k - 1) & 0x3) << 4);
	val |= (((m - 1) & 0x3) << 0);
	write32(ccu_base + reg_pll_ctrl, val);
	sdelay(200);

	/* Switch clock source back to PLL */
	val = (2 << 0) | (1 << 8) | (2 << 16);
	write32(ccu_base + reg_axi_cfg, val);
}

