/*
 * boot_nuttx.c - NuttX RTOS boot support for awboot
 *
 * SPDX-License-Identifier: MIT
 */

#include "main.h"
#include "arm32.h"
#include "debug.h"

/**
 * detect_image_type - Detect image type from EGON header magic
 * @addr: Image load address
 *
 * Returns: IMAGE_TYPE_NUTTX, IMAGE_TYPE_LINUX, or IMAGE_TYPE_UNKNOWN
 */
image_type_t detect_image_type(unsigned char *addr)
{
	struct egon_header_t *hdr = (struct egon_header_t *)addr;

	/* Check for NuttX magic */
	if (memcmp(hdr->magic, EGON_MAGIC_NUTTX, 8) == 0) {
		return IMAGE_TYPE_NUTTX;
	}

	/* Check for Linux magic (legacy support) */
	if (memcmp(hdr->magic, EGON_MAGIC_LINUX, 8) == 0) {
		return IMAGE_TYPE_LINUX;
	}

	return IMAGE_TYPE_UNKNOWN;
}

/**
 * boot_nuttx - Boot NuttX RTOS image
 * @image: Image info structure containing load addresses
 *
 * NuttX images have EGON header prepended. Entry point is after the header.
 * Boot parameters:
 *   r0 = 0
 *   r1 = 0 (NuttX doesn't use machine ID)
 *   r2 = DTB address (optional, may be 0)
 *
 * Returns: Should never return on success
 */
int boot_nuttx(image_info_t *image)
{
	struct egon_header_t *hdr = (struct egon_header_t *)image->dest;
	void (*entry)(int, int, unsigned int);
	unsigned int entry_addr;

#if 0  /* Debug: dump first 16 bytes */
	info("NuttX: loaded data at 0x%08x:\r\n", (unsigned int)image->dest);
	info("  %02x %02x %02x %02x %02x %02x %02x %02x\r\n",
	     ((unsigned char*)image->dest)[0], ((unsigned char*)image->dest)[1],
	     ((unsigned char*)image->dest)[2], ((unsigned char*)image->dest)[3],
	     ((unsigned char*)image->dest)[4], ((unsigned char*)image->dest)[5],
	     ((unsigned char*)image->dest)[6], ((unsigned char*)image->dest)[7]);
	info("  %02x %02x %02x %02x %02x %02x %02x %02x\r\n",
	     ((unsigned char*)image->dest)[8], ((unsigned char*)image->dest)[9],
	     ((unsigned char*)image->dest)[10], ((unsigned char*)image->dest)[11],
	     ((unsigned char*)image->dest)[12], ((unsigned char*)image->dest)[13],
	     ((unsigned char*)image->dest)[14], ((unsigned char*)image->dest)[15]);
#endif

	/* Verify magic */
	if (memcmp(hdr->magic, EGON_MAGIC_NUTTX, 8) != 0) {
		error("NuttX: invalid magic\r\n");
		return -1;
	}

	/* Entry point is at the start of image (eGON header has jump instruction) */
	entry_addr = (unsigned int)image->dest;
	entry = (void (*)(int, int, unsigned int))entry_addr;

	info("NuttX: entry=0x%08x, dtb=0x%08x\r\n",
	     entry_addr, (unsigned int)image->of_dest);

	/* Disable MMU, caches, interrupts before jumping (same proven sequence as
	 * boot_linux). NOTE: do NOT call arm32_dcache_clean_invalidate() here — its
	 * `mcr p15,0,r0,c7,c14,0` is an ARM926 op; on Cortex-A7 (ARMv7-A) c7,c14,opc2=0
	 * is UNDEFINED and traps to the undef vector (awboot dies at pc=0x4 before the
	 * jump). Disabling the D-cache cleans/writes back as needed for the handoff. */
	arm32_mmu_disable();
	arm32_dcache_disable();
	arm32_icache_disable();
	arm32_interrupt_disable();

	/* Jump to NuttX: r0=0, r1=0, r2=DTB */
	entry(0, 0, (unsigned int)image->of_dest);

	/* Should never reach here */
	return -1;
}

#ifndef __ARM32_H__
#define __ARM32_H__

#ifdef __cplusplus
extern "C" {
#endif

#include <stdint.h>

static inline uint32_t arm32_read_p15_c1(void)
{
	uint32_t value;

	__asm__ __volatile__("mrc p15, 0, %0, c1, c0, 0" : "=r"(value) : : "memory");

	return value;
}

static inline void arm32_write_p15_c1(uint32_t value)
{
	__asm__ __volatile__("mcr p15, 0, %0, c1, c0, 0" : : "r"(value) : "memory");
	arm32_read_p15_c1();
}

static inline void arm32_interrupt_enable(void)
{
	uint32_t tmp;

	__asm__ __volatile__("mrs %0, cpsr\n"
						 "bic %0, %0, #(1<<7)\n"
						 "msr cpsr_cxsf, %0"
						 : "=r"(tmp)
						 :
						 : "memory");
}

static inline void arm32_interrupt_disable(void)
{
	uint32_t tmp;

	__asm__ __volatile__("mrs %0, cpsr\n"
						 "orr %0, %0, #(1<<7)\n"
						 "msr cpsr_cxsf, %0"
						 : "=r"(tmp)
						 :
						 : "memory");
}

static inline void arm32_mmu_enable(void)
{
	uint32_t value = arm32_read_p15_c1();
	arm32_write_p15_c1(value | (1 << 0));
}

static inline void arm32_mmu_disable(void)
{
	uint32_t value = arm32_read_p15_c1();
	arm32_write_p15_c1(value & ~(1 << 0));
}

static inline void arm32_dcache_enable(void)
{
	uint32_t value = arm32_read_p15_c1();
	arm32_write_p15_c1(value | (1 << 2));
}

static inline void arm32_dcache_disable(void)
{
	uint32_t value = arm32_read_p15_c1();
	arm32_write_p15_c1(value & ~(1 << 2));
}

static inline void arm32_icache_enable(void)
{
	uint32_t value = arm32_read_p15_c1();
	arm32_write_p15_c1(value | (1 << 12));
}

static inline void arm32_icache_disable(void)
{
	uint32_t value = arm32_read_p15_c1();
	arm32_write_p15_c1(value & ~(1 << 12));
}

static inline void arm32_icache_invalidate(void)
{
	__asm__ __volatile__("mcr p15, 0, %0, c7, c5, 0" : : "r"(0) : "memory");
}

static inline void arm32_dcache_clean_invalidate(void)
{
	/* Clean and invalidate entire D-Cache */
	/* Use c7,c14,0 for ARM926, works on Cortex-A7 too */
	__asm__ __volatile__("mcr p15, 0, %0, c7, c14, 0" : : "r"(0) : "memory");
	/* Data memory barrier - use mcr for ARM926 compatibility */

