static int t113_i2c_interrupt(int irq, void *context, void *arg)
{
  FAR struct t113_i2c_priv_s *priv = (FAR struct t113_i2c_priv_s *)arg;
  uint32_t status;
  uint32_t cntr;

  status = I2C_GETREG(priv, I2C_STAT_OFFSET);

  switch (status)
    {
      case I2C_STAT_TX_START:
      case I2C_STAT_TX_RESTART:
        {
          FAR struct i2c_msg_s *msg = &priv->msgs[priv->msg_idx];
          uint8_t byte = (msg->addr << 1) | (priv->is_read ? 1 : 0);
          I2C_PUTREG(priv, I2C_DATA_OFFSET, byte);
          priv->state = I2C_STATE_ADDR_SEND;
        }
        break;

      case I2C_STAT_TX_AW_ACK:
        if (priv->bytes_remaining > 0)
          {
            I2C_PUTREG(priv, I2C_DATA_OFFSET, *priv->buffer++);
            priv->bytes_remaining--;
            priv->state = I2C_STATE_DATA_SEND;
          }
        else
          {
            i2c_next_message(priv);
          }
        break;

      case I2C_STAT_TXD_ACK:
        if (priv->bytes_remaining > 0)
          {
            I2C_PUTREG(priv, I2C_DATA_OFFSET, *priv->buffer++);
            priv->bytes_remaining--;
          }
        else
          {
            i2c_next_message(priv);
          }
        break;

      case I2C_STAT_TX_AR_ACK:
        cntr = I2C_GETREG(priv, I2C_CNTR_OFFSET);
        if (priv->bytes_remaining > 1)
          {
            cntr |= I2C_CNTR_ACK;
          }
        else
          {
            cntr &= ~I2C_CNTR_ACK;
          }
        I2C_PUTREG(priv, I2C_CNTR_OFFSET, cntr);
        priv->state = I2C_STATE_DATA_RECV;
        break;

      case I2C_STAT_RXD_ACK:
      case I2C_STAT_RXD_NAK:
        *priv->buffer++ = I2C_GETREG(priv, I2C_DATA_OFFSET);
        priv->bytes_remaining--;

        if (priv->bytes_remaining > 0)
          {
            cntr = I2C_GETREG(priv, I2C_CNTR_OFFSET);
            if (priv->bytes_remaining > 1)
              {
                cntr |= I2C_CNTR_ACK;
              }
            else
              {
                cntr &= ~I2C_CNTR_ACK;
              }
            I2C_PUTREG(priv, I2C_CNTR_OFFSET, cntr);
          }
        else
          {
            i2c_next_message(priv);
          }
        break;

      case I2C_STAT_BUS_ERROR:
      case I2C_STAT_LOST_ARB:
      case I2C_STAT_TX_AW_NAK:
      case I2C_STAT_TX_AR_NAK:
      case I2C_STAT_TXD_NAK:
      default:
        /* Error / NAK / unexpected status (e.g. no device on the bus).
         * Abort the transfer immediately: send STOP, DISABLE the I2C
         * interrupt and clear the flag, then wake the waiter.  Disabling
         * the interrupt here is essential — otherwise an error state the
         * controller keeps re-asserting causes a back-to-back interrupt
         * storm that starves the scheduler so the tickwait timeout never
         * fires, hanging the whole system (froze boot during an i2cdetect).
         */

        if (status != I2C_STAT_TX_AW_NAK && status != I2C_STAT_TX_AR_NAK &&
            status != I2C_STAT_TXD_NAK)
          {
            i2cerr("I2C error/unexpected status: 0x%02lx\n",
                   (unsigned long)status);
          }

        priv->state  = I2C_STATE_ERROR;
        priv->result = -EIO;

        cntr  = I2C_GETREG(priv, I2C_CNTR_OFFSET);
        cntr |= (I2C_CNTR_STOP | I2C_CNTR_INT_FLAG); /* STOP + W1C-clear flag */
        cntr &= ~(I2C_CNTR_INT_EN | I2C_CNTR_START);
        I2C_PUTREG(priv, I2C_CNTR_OFFSET, cntr);

        nxsem_post(&priv->wait);
        return OK;
    }

  /* Clear INT_FLAG to advance the TWI engine to the next state.
   * On real silicon INT_FLAG is WRITE-1-TO-CLEAR (vendor twi-sunxi-core.c:
   * "intflag bit is write-1-to-clear bit"); writing 0 leaves it set, so the
   * IRQ stays asserted and the ISR re-fires back-to-back forever (interrupt
   * storm that froze the whole system during i2cdetect).  Also mask START/
   * STOP (self-clear-to-0 bits) so we don't accidentally re-trigger them.
   */

  cntr  = I2C_GETREG(priv, I2C_CNTR_OFFSET);
  cntr |= I2C_CNTR_INT_FLAG;
  cntr &= ~(I2C_CNTR_START | I2C_CNTR_STOP);
  I2C_PUTREG(priv, I2C_CNTR_OFFSET, cntr);

  return OK;
}

