static struct wdog_s g_bl_wait_wd;
static volatile bool g_bl_wait_expired;

static void bl_wait_expired(wdparm_t arg)
{
  UNUSED(arg);
  g_bl_wait_expired = true;
}

#include "f1c100s_bootkv.h"
#include "f1c100s_partitions.h"
