static int boot_should_stay(FAR const struct f1c100s_bootkv_s *kv, int kvret)
{
  if (kvret == F1C100S_BOOTKV_BLANK)
    {
      syslog(LOG_WARNING, "boot: KV blank, stay in BL\n");
      return 1;
    }

  if (kvret < 0)
    {
      syslog(LOG_ERR, "boot: KV read %d, stay in BL\n", kvret);
      return 1;
    }

  if (kv->fail_count >= (uint32_t)CONFIG_F1C100S_BOOT_FAIL_LIMIT)
    {
      syslog(LOG_ERR, "boot: fail_count %u >= %d, stay in BL\n",
             (unsigned)kv->fail_count, CONFIG_F1C100S_BOOT_FAIL_LIMIT);
      return 1;
    }

  if (kv->ap_size == 0 || kv->ap_size > F1C100S_PART_AP_SIZE ||
      kv->ap_size > F1C100S_AP_STAGING_SIZE)
    {
      syslog(LOG_ERR, "boot: ap_size %u invalid, stay in BL\n",
             (unsigned)kv->ap_size);
      return 1;
    }

  return 0;
}

static void noreturn_function boot_stay_in_bl(void)
{
  syslog(LOG_WARNING, "boot: staying in BL, waiting for fastboot\n");
  f1c100s_boot_status("Waiting for fastboot...");

#ifdef CONFIG_SYSTEM_FASTBOOTD
  {
    int pid = task_create("fastbootd",
                          CONFIG_SYSTEM_FASTBOOTD_PRIORITY,
                          CONFIG_SYSTEM_FASTBOOTD_STACKSIZE,
                          fastbootd_main, NULL);
    if (pid < 0)
      {
        syslog(LOG_ERR, "boot: fastbootd task_create failed %d\n", pid);
      }
    else
      {
        syslog(LOG_INFO, "boot: fastbootd pid %d\n", pid);
      }
  }
#endif

  /* Wait for a host; feed WDT so a stuck BL still resets through
   * awboot. On timeout, try the current AP (spec §2 / §5).
   */

  g_bl_wait_expired = false;
  wd_start(&g_bl_wait_wd, SEC2TICK(CONFIG_F1C100S_BL_WAIT_SEC),
           bl_wait_expired, 0);

  while (!g_bl_wait_expired)
    {
#ifdef CONFIG_F1C100S_WDT
      f1c100s_wdtfeed_keepalive();
#endif
      usleep(200000);
    }

  syslog(LOG_WARNING, "boot: fastboot wait timed out, trying AP\n");
  f1c100s_boot_status("Booting AP");

  {
    struct f1c100s_bootkv_s kv;
    int kvret = f1c100s_bootkv_read(&kv);
    if (kvret == 0 && !boot_should_stay(&kv, kvret))
      {
        (void)boot_load_and_jump(&kv);
      }
  }

  for (; ; )
    {
#ifdef CONFIG_F1C100S_WDT
      f1c100s_wdtfeed_keepalive();
#endif
      usleep(200000);
    }
}

static int boot_load_and_jump(FAR struct f1c100s_bootkv_s *kv)
{
  FAR uint8_t *staging = (FAR uint8_t *)(uintptr_t)F1C100S_AP_STAGING;
  uint32_t crc;
  uint32_t copy;
  irqstate_t flags;
  int ret;
  f1c100s_tramp_t tramp;

  syslog(LOG_INFO, "boot: loading AP %u bytes from 0x%x\n",
         (unsigned)kv->ap_size, (unsigned)F1C100S_PART_AP_OFFSET);

  ret = f1c100s_bootkv_flash_read(F1C100S_PART_AP_OFFSET,
                                  staging, kv->ap_size);
  if (ret < 0)
    {
      syslog(LOG_ERR, "boot: AP flash read failed %d\n", ret);
      return ret;
    }

  if (memcmp(staging + 4, "eGON.NTX", 8) != 0)
    {
      syslog(LOG_ERR, "boot: AP missing eGON.NTX magic\n");
      return -ENOEXEC;
    }

  crc = crc32(staging, kv->ap_size);
  if (crc != kv->ap_crc32)
    {
      syslog(LOG_ERR, "boot: AP crc 0x%08x != kv 0x%08x\n",
             (unsigned)crc, (unsigned)kv->ap_crc32);
      f1c100s_boot_status("Update failed, retry");
      return -EILSEQ;
    }

  kv->fail_count++;
  ret = f1c100s_bootkv_write(kv);
  if (ret < 0)
    {
      syslog(LOG_ERR, "boot: fail_count write failed %d\n", ret);
      return ret;
    }

  copy = (kv->ap_size + 3u) & ~3u;
  if (copy > F1C100S_AP_STAGING_SIZE)
    {
      copy = kv->ap_size & ~3u;
    }

  memcpy((void *)(uintptr_t)F1C100S_TRAMPOLINE_ADDR,
         g_trampoline, sizeof(g_trampoline));

  syslog(LOG_INFO, "boot: jumping to AP at 0x%08x\n",
         (unsigned)F1C100S_AP_LOAD_ADDR);
  f1c100s_boot_status("Booting AP");

  flags = up_irq_save();
  UNUSED(flags);

  tramp = (f1c100s_tramp_t)(uintptr_t)F1C100S_TRAMPOLINE_ADDR;
  tramp(F1C100S_AP_STAGING, F1C100S_AP_LOAD_ADDR, copy,
        F1C100S_AP_LOAD_ADDR);

  /* Not reached. */

  return -EIO;
}

