int board_boot_image(FAR const char *path, uint32_t hdr_size)
{
  struct f1c100s_bootkv_s kv;
  int ret;

  UNUSED(path);
  UNUSED(hdr_size);

  memset(&kv, 0, sizeof(kv));
  ret = f1c100s_bootkv_read(&kv);

  if (boot_should_stay(&kv, ret))
    {
      boot_stay_in_bl();
    }

  ret = boot_load_and_jump(&kv);
  syslog(LOG_ERR, "boot: load/jump failed %d, stay in BL\n", ret);
  boot_stay_in_bl();
}

