syslog(LOG_WARNING, "boot: fastboot wait timed out, trying AP\n");
f1c100s_boot_status("Booting AP");

{
  struct f1c100s_bootkv_s kv;
  int kvret = f1c100s_bootkv_read(&kv);

  /* Deliberately ignore fail_count here: it is exactly the reason we
   * may have stayed in the first place, and re-checking it would make
   * this timeout a no-op whenever that was the cause -- the board
   * would feed the WDT forever with no way out except fastboot ever
   * connecting. The timeout's job is "don't get stuck forever with
   * no host attached"; only a genuinely unusable image (unreadable
   * KV, or ap_size out of bounds) can still block it.
   */

  if (!boot_kv_unusable(&kv, kvret))
    {
      syslog(LOG_WARNING,
             "boot: timeout override, jumping to AP despite "
             "fail_count %u\n", (unsigned)kv.fail_count);
      (void)boot_load_and_jump(&kv);
    }
}

