  g_crashlog.seq    = seq + 1;
  g_crashlog.sp     = (uint32_t)sp;
  g_crashlog.lineno = (uint32_t)lineno;
  crashlog_copystr(g_crashlog.filename, sizeof(g_crashlog.filename),
                   filename);
