      FAR const uint32_t *r = (FAR const uint32_t *)regs;
      unsigned i;

      g_crashlog.nregs = 16;
      for (i = 0; i < 16; i++)
        {
          g_crashlog.regs[i] = r[i];
        }

      g_crashlog.pc = r[15];
    }

}
