int f1c100s_st7789_initialize(void)
{
  g_spi = f1c100s_spibus_initialize(1);
  if (g_spi == NULL)
    {
      syslog(LOG_ERR, "st7789: SPI1 init failed\n");
      return -ENODEV;
    }

  f1c_gpio_config(ST7789_DC_PORT, ST7789_DC_PIN,
                  GPIO_OUT, GPIO_NOPULL, GPIO_DRV);
  f1c_gpio_config(ST7789_RST_PORT, ST7789_RST_PIN,
                  GPIO_OUT, GPIO_NOPULL, GPIO_DRV);
  f1c_gpio_write(ST7789_DC_PORT, ST7789_DC_PIN, true);
  f1c_gpio_write(ST7789_RST_PORT, ST7789_RST_PIN, false);
  up_mdelay(10);
  f1c_gpio_write(ST7789_RST_PORT, ST7789_RST_PIN, true);
  up_mdelay(120);

  st7789_select();
  st7789_cmd(ST7789_SWRESET);
  st7789_deselect();
  up_mdelay(150);

  st7789_select();
  st7789_cmd(ST7789_SLPOUT);
  st7789_deselect();
  up_mdelay(120);

  st7789_select();
  st7789_cmd(ST7789_COLMOD);
  st7789_data(0x55);
  st7789_cmd(ST7789_MADCTL);
  st7789_data(0x00);
  st7789_cmd(ST7789_INVON);
  st7789_cmd(ST7789_NORON);
  st7789_cmd(ST7789_DISPON);
  st7789_deselect();
  up_mdelay(20);

  g_ready = true;
  f1c100s_boot_status("LOGO");
  syslog(LOG_INFO, "st7789: 240x240 on SPI1 DC=P%c%d RST=P%c%d\n",
         'A' + CONFIG_F1C100S_ST7789_DC_PORT,
         CONFIG_F1C100S_ST7789_DC_PIN,
         'A' + CONFIG_F1C100S_ST7789_RST_PORT,
         CONFIG_F1C100S_ST7789_RST_PIN);
  return 0;
}

void f1c100s_boot_status(const char *msg)
{
  if (!g_ready)
    {
      return;
    }

  st7789_fill(COLOR_BG);
  st7789_text(16, 40, "F1C100s BL");
  if (msg != NULL)
    {
      st7789_text(16, 120, msg);
    }
}

