487	static uint32_t spi_read_rx_fifo(sunxi_spi_t *spi, uint8_t *buf, uint32_t len)
488	{
489		uint32_t remaining = len;
490		uint32_t loop;
491	
492		/* Read the RX FIFO one byte per access.
493		 *
494		 * The sun6i SPI RXDATA register pops exactly ONE byte per read regardless
495		 * of the access width (a 32-bit read returns the next byte in bits[7:0]).
496		 * This matches NuttX (reads byte-at-a-time: getreg32 & 0xFF) and real
497		 * silicon. The old "read 4 bytes via a single read32" yielded 1 real byte
498		 * + 3 zero bytes (a 4x-stretched image, failing awboot's eGON/NTX magic).
499		 * Byte-wise reads are correct everywhere; throughput is SPI-clock bound,
500		 * not read-width bound, so there is no meaningful cost.
501		 */
502		while (remaining > 0) {
503			loop = 0;
504			while (spi_query_rxfifo(spi) < 1) {
505				loop++;
506				if (loop == 100000) {
507					warning("spi_read_rx_fifo: stuck @1B rem=%lu FSR=0x%08lx ISR=0x%08lx TCR=0x%08lx MBC=0x%08lx\r\n",
508						(unsigned long)remaining,
509						(unsigned long)read32(spi->base + SPI_FSR),
510						(unsigned long)read32(spi->base + SPI_ISR),
511						(unsigned long)read32(spi->base + SPI_TCR),
512						(unsigned long)read32(spi->base + SPI_MBC));
513				}
514			};
515			*buf++ = read8(spi->base + SPI_RXD);
516			remaining--;
517		}
518		return len;
519	}
