187	static void noreturn_function boot_stay_in_bl(void)
188	{
189	  syslog(LOG_WARNING, "boot: staying in BL, waiting for fastboot\n");
190	  f1c100s_boot_status("Waiting for fastboot...");
191	
192	#ifdef CONFIG_EXAMPLES_FB
193	  /* The BL entry point is miniboot_main(), so rcS is not reached here.
194	   * Launch the existing fb example only on the KV-selected BL path. */
195	  {
196	    int pid = task_create("fb", 100, 2048, fb_main, g_bl_fb_argv);
197	    if (pid < 0)
198	      {
199	        syslog(LOG_ERR, "boot: fb task_create failed %d\n", pid);
200	      }
201	  }
202	#endif
203	
204	#ifdef CONFIG_SYSTEM_FASTBOOTD
205	  {
206	    int pid = task_create("fastbootd",
207	                          CONFIG_SYSTEM_FASTBOOTD_PRIORITY,
208	                          CONFIG_SYSTEM_FASTBOOTD_STACKSIZE,
209	                          fastbootd_main, NULL);
210	    if (pid < 0)
211	      {
212	        syslog(LOG_ERR, "boot: fastbootd task_create failed %d\n", pid);
213	      }
214	    else
215	      {
216	        syslog(LOG_INFO, "boot: fastbootd pid %d\n", pid);
217	      }
218	  }
219	#endif
220	
221	  /* An explicit reboot-to-bootloader request must not expire into AP. */
222	  {
223	    struct f1c100s_bootkv_s current;
224	    int current_ret = f1c100s_bootkv_read(&current);
225	    if (current_ret == 0 &&
226	        current.active_flag == F1C100S_BOOTKV_ACTIVE_BOOTLOADER)
227	      {
228	        for (;;)
229	          {
230	#ifdef CONFIG_F1C100S_WDT
231	            f1c100s_wdtfeed_keepalive();
232	#endif
233	            usleep(200000);
234	          }
235	      }
236	  }
237	
238	  /* Wait for a host; feed WDT so a stuck BL still resets through
239	   * awboot. On timeout, try the current AP (spec §2 / §5).
240	   */
241	
242	  g_bl_wait_expired = false;
243	  wd_start(&g_bl_wait_wd, SEC2TICK(CONFIG_F1C100S_BL_WAIT_SEC),
244	           bl_wait_expired, 0);
245	
246	  while (!g_bl_wait_expired)
247	    {
248	#ifdef CONFIG_F1C100S_WDT
249	      f1c100s_wdtfeed_keepalive();
250	#endif
251	      usleep(200000);
252	    }
253	
254	  syslog(LOG_WARNING, "boot: fastboot wait timed out, trying AP\n");
255	  f1c100s_boot_status("Booting AP");
256	
257	  {
258	    struct f1c100s_bootkv_s kv;
259	    int kvret = f1c100s_bootkv_read(&kv);
260	
261	    /* Deliberately ignore fail_count here: it is exactly the reason we
262	     * may have stayed in the first place, and re-checking it would make
263	     * this timeout a no-op whenever that was the cause -- the board
264	     * would feed the WDT forever with no way out except fastboot ever
265	     * connecting. The timeout's job is "don't get stuck forever with
266	     * no host attached"; only a genuinely unusable image (unreadable
267	     * KV, or ap_size out of bounds) can still block it.
268	     */
269	
270	    if (!boot_kv_unusable(&kv, kvret))
271	      {
272	        syslog(LOG_WARNING,
273	               "boot: timeout override, jumping to AP despite "
274	               "fail_count %u\n", (unsigned)kv.fail_count);
275	        (void)boot_load_and_jump(&kv);
276	      }
277	  }
278	
279	  for (; ; )
280	    {
281	#ifdef CONFIG_F1C100S_WDT
282	      f1c100s_wdtfeed_keepalive();
283	#endif
284	      usleep(200000);
285	    }
