469	
470	  sparse = (FAR struct fastboot_sparse_header_s *)chunk_ptr;
471	  if (sparse->magic != FASTBOOT_SPARSE_MAGIC)
472	    {
473	      ret = fastboot_flash_write(fd, 0, context->download_buffer,
474	                                 context->download_size);
475	      goto end;
476	    }
477	
478	  if (context->total_imgsize == 0)
479	    {
480	      context->total_imgsize = sparse->blk_sz * sparse->total_blks;
481	    }
482	
483	  chunk_num = sparse->total_chunks;
484	  chunk_ptr += FASTBOOT_SPARSE_HEADER;
485	
486	  while (chunk_ptr < end_ptr && chunk_num--)
487	    {
488	      FAR struct fastboot_chunk_header_s *chunk =
489	        (FAR struct fastboot_chunk_header_s *)chunk_ptr;
490	
491	      chunk_ptr += FASTBOOT_CHUNK_HEADER;
492	
493	      switch (chunk->chunk_type)
