498	              ret = fastboot_flash_write(fd, context->download_offset,
499	                                         chunk_ptr, chunk_size);
500	              if (ret < 0)
501	                {
502	                  goto end;
503	                }
504	
505	              context->download_offset += chunk_size;
506	              chunk_ptr += chunk_size;
507	            }
508	            break;
509	          case FASTBOOT_CHUNK_FILL:
510	            {
511	              uint32_t fill_data = be32toh(*(FAR uint32_t *)chunk_ptr);
512	              uint32_t chunk_size = chunk->chunk_sz * sparse->blk_sz;
513	              ret = ffastboot_flash_fill(fd, context->download_offset,
514	                                         fill_data, sparse->blk_sz,
515	                                         chunk->chunk_sz);
516	              if (ret < 0)
517	                {
518	                  goto end;
519	                }
520	
521	              context->download_offset += chunk_size;
522	              chunk_ptr += 4;
523	            }
524	            break;
525	          case FASTBOOT_CHUNK_DONT_CARE:
526	          case FASTBOOT_CHUNK_CRC32:
