539	 ****************************************************************************/
540	
541	static uint8_t w25_waitwritecomplete(struct w25_dev_s *priv)
542	{
543	  uint8_t status;
544	
545	  /* Loop as long as the memory is busy with a write cycle. Device sets BUSY
546	   * flag to a 1 state whhen previous write or erase command is still
547	   * executing and during this time, device will ignore further instructions
548	   * except for "Read Status Register" and "Erase/Program Suspend"
549	   * instructions.
550	   */
551	
552	  do
553	    {
554	      /* Select this FLASH part */
555	
556	      SPI_SELECT(priv->spi, SPIDEV_FLASH(0), true);
557	
558	      /* Send "Read Status Register (RDSR)" command */
559	
560	      SPI_SEND(priv->spi, W25_RDSR);
561	
562	      /* Send a dummy byte to generate the clock needed to shift out the
563	       * status
564	       */
565	
566	      status = SPI_SEND(priv->spi, W25_DUMMY);
567	
568	      /* Deselect the FLASH */
569	
570	      SPI_SELECT(priv->spi, SPIDEV_FLASH(0), false);
571	
572	      /* Given that writing could take up to few tens of milliseconds, and
573	       * erasing could take more.  The following short delay in the "busy"
574	       * case will allow other peripherals to access the SPI bus.
575	       * Delay would slow down writing too much, so go to sleep only if
576	       * previous operation was not a page program operation.
577	       */
578	
579	      if (priv->prev_instr != W25_PP && (status & W25_SR_BUSY) != 0)
580	        {
581	          w25_unlock(priv->spi);
582	          nxsig_usleep(1000);
583	          w25_lock(priv->spi);
584	        }
585	    }
586	  while ((status & W25_SR_BUSY) != 0);
587	
588	  return status;
589	}
