50	/* Dump the hex values from dest for len words */
51	
52	static int rundump(FAR struct command_s *cmd)
53	{
54	  unsigned char *cur;
55	  int x, i;
56	  long off, last;
57	
58	  /* Error - start is past EOF */
59	
60	  if (cmd->opts.src > g_hexfile->size)
61	    {
62	      return EOF;
63	    }
64	
65	  /* Show to EOF */
66	
67	  if (cmd->opts.bytes == 0)
68	    {
69	      cmd->opts.bytes = g_hexfile->size;
70	    }
71	
72	  /* Trim length to EOF */
73	
74	  if ((cmd->opts.src + cmd->opts.bytes) > g_hexfile->size)
75	    {
76	      cmd->opts.bytes = g_hexfile->size - cmd->opts.src;
77	    }
78	
79	  /* Show file */
80	
81	  cur  = (unsigned char *)(g_hexfile->buf + cmd->opts.src);
82	  off  = cmd->opts.src;
83	  last = cmd->opts.src + cmd->opts.bytes;
84	
85	  for (; off < last; off += 0x10, cur += 0x10)
86	    {
87	      printf("%08lx ", off);
88	
89	      /* Print hex values */
90	
91	      for (x = 0; x < 0x10; x += cmd->opts.word)
92	        {
93	          if (x % 8 == 0)
94	            {
95	              printf(" ");
96	            }
97	
98	          if (off + x < last)
99	            {
100	              /* Print 1-8 byte hexadecimal number */
101	
102	              switch (cmd->opts.word)
103	                {
104	                case WORD_64:
105	                  {
106	                    uint64_t data = *(uint64_t *)(cur + x);
107	                    printf("%016llx", (unsigned long long)data);
108	                  }
109	                  break;
110	
111	               case WORD_32:
112	                  {
113	                    uint32_t data = *(uint32_t *)(cur + x);
114	                    printf("%08lx", (unsigned long)data);
115	                  }
116	                 break;
117	
118	               case WORD_16:
119	                  {
120	                    uint16_t data = *(uint16_t *)(cur + x);
121	                    printf("%04x", (unsigned int)data);
122	                  }
123	                 break;
124	
125	               case WORD_8:
126	                  {
127	                    uint8_t data = *(uint8_t *)(cur + x);
128	                    printf("%02x", (unsigned int)data);
129	                  }
130	                 break;
131	                }
132	            }
133	          else
134	            {
135	              /* Print space */
136	
137	              for (i = 0; i < cmd->opts.word; i++)
138	                {
139	                  printf("  ");
140	                }
141	            }
142	
143	          printf(" ");
144	        }
145	
146	      printf(" ");
147	
148	      /* Print character data */
149	
150	      for (x = 0; x < 0x10; x++)
151	        {
152	          if (off + x < last)
153	            {
154	              if (*(cur + x) >= 0x20 && *(cur + x) < 0x80)
155	                {
156	                  printf("%c", *(cur + x));
157	                }
158	              else
159	                {
160	                  printf(".");
161	                }
162	            }
163	          else
164	            {
165	              printf(" ");
166	            }
167	        }
168	
169	      printf("\n");
170	    }
171	
172	  printf("\n");
173	  return 0;
174	}
