176	/* Set the dump command */
177	
178	static int setdump(FAR struct command_s *cmd, int optc, char *opt)
179	{
180	  FAR char *s;
181	  long v;
182	
183	  /* Set defaults */
184	
185	  if (optc == 0)
186	    {
187	      cmd->flags |= CMD_FL_QUIT;
188	      cmd->opts.src = 0;
189	      cmd->opts.len = 0;
190	      cmd->opts.bytes = 0;
191	    }
192	
193	  /* NULL option */
194	
195	  if (opt == NULL)
196	    {
197	      return 0;
198	    }
199	
200	  v = strtoll(opt, &s, 0x10);
201	
202	  /* No value set in option */
203	
204	  if (s == opt)
205	    {
206	      return -1;
207	    }
208	
209	  /* Set options */
210	
211	  switch (optc)
212	    {
213	    case 0:
214	      /* Set offset */
215	
216	      cmd->opts.src = v;
217	      optc++;
218	      break;
219	
220	    case 1:
221	      /* Set length */
222	
223	      cmd->opts.len = v;
224	      cmd->opts.bytes = cmd->opts.len * cmd->opts.word;
225	
226	    default:
227	      optc = 0;
228	    }
229	
230	  return optc;
231	}
