235	 ****************************************************************************/
236	
237	/* Dump command */
238	
239	int hexdump(FAR struct command_s *cmd, int optc, char *opt)
240	{
241	  /* Invalid command */
242	
243	  if (cmd == NULL || cmd->id != CMD_DUMP)
244	    {
245	      return -EINVAL;
246	    }
247	
248	  /* Set/run dump */
249	
250	  if (optc >= 0)
251	    {
252	      optc = setdump(cmd, optc, opt);
253	    }
254	  else
255	    {
256	      optc = rundump(cmd);
257	    }
258	
259	  return optc;
260	}
