   * partition with ftl_initialize() to get a real block device
   * (/dev/mtdblock1), same as the AT24 EEPROM above, instead of
   * a raw MTD character node. Tests whether NSH dd/hexdump -n
   * open() failures on raw MTD nodes (ENOENT via
   * block_proxy()/bchdev_register()) go away when the node is
   * already a genuine block device instead of relying on that
   * proxy to synthesize one on the fly. See
   * docs/issues/fastboot_erase_f1c100s.md.
   */
  {
    struct mtd_geometry_s geo;
    int gret;

    memset(&geo, 0, sizeof(geo));
    gret = MTD_IOCTL(mtd, MTDIOC_GEOMETRY,
                     (unsigned long)(uintptr_t)&geo);
    if (gret == 0 && geo.blocksize != 0)
      {
        FAR struct mtd_dev_s *resv_part =
          mtd_partition(mtd,
                        F1C100S_PART_RESV_OFFSET /
                        (off_t)geo.blocksize,
                        F1C100S_PART_RESV_SIZE /
                        (off_t)geo.blocksize);
        if (resv_part != NULL)
