static int boot_should_stay(FAR const struct f1c100s_bootkv_s *kv, int kvret)
{
  if (boot_kv_unusable(kv, kvret))
    {
      return 1;
    }

  if (kv->fail_count >= (uint32_t)CONFIG_F1C100S_BOOT_FAIL_LIMIT)
    {
      syslog(LOG_ERR, "boot: fail_count %u >= %d, stay in BL\n",
             (unsigned)kv->fail_count, CONFIG_F1C100S_BOOT_FAIL_LIMIT);
      return 1;
    }

  if (kv->active_flag == F1C100S_BOOTKV_ACTIVE_BOOTLOADER)
    {
      syslog(LOG_WARNING,
             "boot: explicit bootloader request, stay in BL\n");
      return 1;
    }

  return 0;
}

