151	    UNUSED(buf);
152	
153	    apacket_uv_t *up;
154	
155	    if (nread == UV_ENOBUFS) {
156	        /* No frame available, stop read events for now */
157	        uv_read_stop(stream);
158	        return;
159	    }
160	
161	    if (nread == 0) {
162	        /* No data available. This should not happen. */
163	        if (client->cur_len <= 0) {
164	            /* Release memory waiting for next frame */
165	            adb_hal_apacket_release(&client->client, &client->cur_packet->p);
166	            client->cur_packet = NULL;
