157	static void f1c100s_tcon_init(const struct f1c100s_lcd_config_s *cfg)
158	{
159	  uint32_t val;
160	  uint32_t bp;
161	  uint32_t total;
162	  int timeout;
163	
164	  /* PLL_VIDEO. Bit 28 is LOCK (read-only). Do not wait forever. */
165	
166	  putreg32(cfg->pll, F1C_CCU_BASE + CCU_PLL_VIDEO_CTRL);
167	  for (timeout = 10000;
168	       timeout > 0 &&
169	       !(getreg32(F1C_CCU_BASE + CCU_PLL_VIDEO_CTRL) & (1u << 28));
170	       timeout--)
171	    {
172	    }
173	
174	  if (timeout == 0)
175	    {
176	      syslog(LOG_ERR, "f1c100s_fb: PLL_VIDEO lock timeout, pll=0x%08x\n",
177	             (unsigned)getreg32(F1C_CCU_BASE + CCU_PLL_VIDEO_CTRL));
178	    }
179	
180	  /* Module clocks: DEBE/DEFE/TCON from PLL_VIDEO, plus DRAM ports */
181	
182	  putreg32(1u << 31, F1C_CCU_BASE + CCU_BE_CLK);
183	  putreg32(1u << 31, F1C_CCU_BASE + CCU_FE_CLK);
184	  putreg32(1u << 31, F1C_CCU_BASE + CCU_TCON_CLK);
185	
186	  val = getreg32(F1C_CCU_BASE + CCU_DRAM_CLK_GATING);
187	  val |= CCU_DRAM_GATE_DEBE | CCU_DRAM_GATE_DEFE;
188	  putreg32(val, F1C_CCU_BASE + CCU_DRAM_CLK_GATING);
189	
190	  val = getreg32(F1C_CCU_BASE + CCU_BUS_CLK_GATING1);
191	  val |= CCU_CLK_GATE_TCON | CCU_CLK_GATE_DEBE | CCU_CLK_GATE_DEFE;
192	  putreg32(val, F1C_CCU_BASE + CCU_BUS_CLK_GATING1);
193	
194	  val = getreg32(F1C_CCU_BASE + CCU_BUS_SOFT_RST1);
195	  val &= ~(CCU_CLK_GATE_TCON | CCU_CLK_GATE_DEBE | CCU_CLK_GATE_DEFE);
196	  putreg32(val, F1C_CCU_BASE + CCU_BUS_SOFT_RST1);
197	  val |= CCU_CLK_GATE_TCON | CCU_CLK_GATE_DEBE | CCU_CLK_GATE_DEFE;
198	  putreg32(val, F1C_CCU_BASE + CCU_BUS_SOFT_RST1);
199	
200	  /* Disable TCON and tristate pads while programming */
201	
202	  putreg32(0, F1C100S_TCON_BASE + TCON_CTRL);
203	  putreg32(0, F1C100S_TCON_BASE + TCON_INT0);
204	  putreg32(0x0fffffff, F1C100S_TCON_BASE + TCON_T0_CLK);
205	  putreg32(0xffffffff, F1C100S_TCON_BASE + TCON_T0_IO_CTRL1);
206	  putreg32(0xffffffff, F1C100S_TCON_BASE + TCON_T1_IO_CTRL1);
207	
208	  bp = cfg->vbp + cfg->vsw;
209	  val = (1u << 31) | (bp << 4);
210	  putreg32(val, F1C100S_TCON_BASE + TCON_T0_CTRL);
211	
212	  /* DCLK gate is bits 31:28 (linux bit 31; xboot writes 0xf). */
213	
214	  putreg32(TCON_T0_CLK_GATE | cfg->clkdiv, F1C100S_TCON_BASE + TCON_T0_CLK);
215	
216	  val = ((cfg->width - 1) << 16) | (cfg->height - 1);
217	  putreg32(val, F1C100S_TCON_BASE + TCON_T0_TIMING0);
218	
219	  total = cfg->width + cfg->hbp + cfg->hfp + cfg->hsw;
220	  val = ((total - 1) << 16) | (cfg->hbp + cfg->hsw - 1);
221	  putreg32(val, F1C100S_TCON_BASE + TCON_T0_TIMING1);
222	
223	  /* V total is vtotal*2 with no -1 (linux SUN4I_TCON0_BASIC2_V_TOTAL). */
224	
225	  total = cfg->height + cfg->vbp + cfg->vfp + cfg->vsw;
226	  val = ((total * 2) << 16) | (cfg->vbp + cfg->vsw - 1);
227	  putreg32(val, F1C100S_TCON_BASE + TCON_T0_TIMING2);
228	
229	  val = ((cfg->hsw - 1) << 16) | (cfg->vsw - 1);
230	  putreg32(val, F1C100S_TCON_BASE + TCON_T0_TIMING3);
231	
232	  putreg32(0, F1C100S_TCON_BASE + TCON_T0_HV_TIMING);
233	  putreg32(0, F1C100S_TCON_BASE + TCON_T0_CPU_IF);
234	
235	  /* 16-bit framebuffer on an 18/24-bit RGB panel: TCON FRM dither. */
236	
237	  putreg32(0x11111111, F1C100S_TCON_BASE + TCON_FRM_SEED0_R);
238	  putreg32(0x11111111, F1C100S_TCON_BASE + TCON_FRM_SEED0_G);
239	  putreg32(0x11111111, F1C100S_TCON_BASE + TCON_FRM_SEED0_B);
240	  putreg32(0x11111111, F1C100S_TCON_BASE + TCON_FRM_SEED1_R);
241	  putreg32(0x11111111, F1C100S_TCON_BASE + TCON_FRM_SEED1_G);
242	  putreg32(0x11111111, F1C100S_TCON_BASE + TCON_FRM_SEED1_B);
243	  putreg32(0x01010000, F1C100S_TCON_BASE + TCON_FRM_TBL0);
244	  putreg32(0x15151111, F1C100S_TCON_BASE + TCON_FRM_TBL1);
245	  putreg32(0x57575555, F1C100S_TCON_BASE + TCON_FRM_TBL2);
246	  putreg32(0x7f7f7777, F1C100S_TCON_BASE + TCON_FRM_TBL3);
247	  putreg32((1u << 31) | (5u << 4), F1C100S_TCON_BASE + TCON_FRM_CTRL);
248	
249	  /* DCLK phase=1, H/V sync active-low, sample on falling DCLK.
250	   * DE stays active-high. INV XORs onto bits 27:24.
251	   */
252	
253	  val = (1u << 28) | (1u << 26) | (1u << 25) | (1u << 24);
254	  val ^= ((uint32_t)cfg->inv << 24);
255	  putreg32(val, F1C100S_TCON_BASE + TCON_T0_IO_CTRL0);
256	  putreg32(0, F1C100S_TCON_BASE + TCON_T0_IO_CTRL1);
257	}
