259	/****************************************************************************
260	 * Name: f1c100s_debe_init
261	 ****************************************************************************/
262	
263	static void f1c100s_debe_init(const struct f1c100s_lcd_config_s *cfg,
264	                              void *fbmem)
265	{
266	  uint32_t val;
267	  uintptr_t addr = (uintptr_t)fbmem;
268	  unsigned int i;
269	
270	  /* Zero the DEBE register block (xboot does 0x800..0x1000 from 0x01e60000). */
271	
272	  for (i = 0; i < 0x800; i += 4)
273	    {
274	      putreg32(0, F1C100S_DEBE_BASE + i);
275	    }
276	
277	  val = ((cfg->height - 1) << 16) | (cfg->width - 1);
278	  putreg32(val, F1C100S_DEBE_BASE + DEBE_DISP_SIZE);
279	  putreg32(val, F1C100S_DEBE_BASE + DEBE_LAY_SIZE(0));
280	  putreg32(0, F1C100S_DEBE_BASE + DEBE_LAY_POS(0));
281	
282	  /* Linewidth is in bits (linux: pitches[0]*8). RGB565 = width << 4. */
283	
284	  putreg32((uint32_t)cfg->width * CONFIG_F1C100S_FB_BPP,
285	           F1C100S_DEBE_BASE + DEBE_LAY_STRIDE(0));
286	
287	  putreg32(addr << 3, F1C100S_DEBE_BASE + DEBE_LAY_FB_ADDRL(0));
288	  putreg32(addr >> 29, F1C100S_DEBE_BASE + DEBE_LAY_FB_ADDRH(0));
289	
290	  /* Do not set ATTCTL0 bit0 (that is global-alpha enable, alpha=0
291	   * makes the layer fully transparent). Layer enable is MODE bit 8.
292	   */
293	
294	  putreg32(0, F1C100S_DEBE_BASE + DEBE_LAY_ATTR0(0));
295	  putreg32(DEBE_FMT_RGB565, F1C100S_DEBE_BASE + DEBE_LAY_ATTR1(0));
296	  putreg32(0x00000000, F1C100S_DEBE_BASE + DEBE_BACKCOLOR);
297	
298	  val = DEBE_MODE_EN | DEBE_MODE_START | DEBE_MODE_LAY0_EN;
299	  putreg32(val, F1C100S_DEBE_BASE + DEBE_MODE_CTRL);
300	
301	  putreg32(DEBE_REGBUFF_LOAD, F1C100S_DEBE_BASE + DEBE_REG_CTRL);
302	}
