308	static void f1c100s_lcd_gpio_init(void)
309	{
310	  /* Configure PD0-PD21 for LCD function (function 2) */
311	
312	  putreg32(0x22222222, F1C_PIO_BASE + 0x6c);  /* PD_CFG0: PD0-PD7 */
313	  putreg32(0x22222222, F1C_PIO_BASE + 0x70);  /* PD_CFG1: PD8-PD15 */
314	  putreg32(0x00222222, F1C_PIO_BASE + 0x74);  /* PD_CFG2: PD16-PD21 */
315	
316	  /* Set drive strength to level 3 */
317	
318	  putreg32(0xffffffff, F1C_PIO_BASE + 0x7c);  /* PD_DRV0 */
319	  putreg32(0x00000fff, F1C_PIO_BASE + 0x80);  /* PD_DRV1 */
320	
321	  /* Disable pull-up/down */
322	
323	  putreg32(0, F1C_PIO_BASE + 0x84);           /* PD_PUL0 */
324	  putreg32(0, F1C_PIO_BASE + 0x88);           /* PD_PUL1 */
