379	
380	#ifdef CONFIG_FB_UPDATE
381	static int f1c100s_updatearea(struct fb_vtable_s *vtable,
382	                              const struct fb_area_s *area)
383	{
384	  /* ARM926EJ-S: Clean entire D-cache to ensure data is in RAM */
385	
386	  __asm__ __volatile__ (
387	    "mov r0, #0\n"
388	    "1:\n"
389	    "mcr p15, 0, r0, c7, c10, 2\n"  /* Clean D-cache line by set/way */
390	    "add r0, r0, #32\n"
391	    "cmp r0, #0x4000\n"
392	    "blt 1b\n"
393	    "mcr p15, 0, r0, c7, c10, 4\n"  /* DSB */
394	    : : : "r0", "memory"
395	  );
396	
397	  return OK;
398	}
399	#endif
