405	/****************************************************************************
406	 * Name: f1c100s_fb_initialize
407	 *
408	 * Description:
409	 *   Initialize the framebuffer driver
410	 *
411	 ****************************************************************************/
412	
413	int f1c100s_fb_initialize(int display)
414	{
415	  struct f1c100s_fb_s *priv = &g_fbdev;
416	  int ret;
417	
418	  /* Check if already initialized */
419	
420	  if (priv->fbmem != NULL)
421	    {
422	      ginfo("F1C100s framebuffer already initialized\n");
423	      return OK;
424	    }
425	
426	  ginfo("Initializing F1C100s framebuffer\n");
427	
428	  /* Allocate framebuffer memory from heap */
429	
430	  priv->fblen = FB_SIZE;
431	  priv->bpp   = CONFIG_F1C100S_FB_BPP;
432	  priv->fbmem = kmm_memalign(4096, priv->fblen);
433	
434	  if (priv->fbmem == NULL)
435	    {
436	      gerr("ERROR: Failed to allocate framebuffer memory\n");
437	      return -ENOMEM;
438	    }
439	
440	  ginfo("Framebuffer: %p, size: %zu\n", priv->fbmem, priv->fblen);
441	
442	  /* Solid red (RGB565 0xf800) so the panel is on before any fb test. */
443	
444	    {
445	      uint16_t *px = (uint16_t *)priv->fbmem;
446	      size_t n = priv->fblen / sizeof(uint16_t);
447	      size_t i;
448	
449	      for (i = 0; i < n; i++)
450	        {
451	          px[i] = 0xf800;
452	        }
453	    }
454	
455	  __asm__ __volatile__ (
456	    "mov r0, #0\n"
457	    "1:\n"
458	    "mcr p15, 0, r0, c7, c10, 2\n"
459	    "add r0, r0, #32\n"
460	    "cmp r0, #0x4000\n"
461	    "blt 1b\n"
462	    "mcr p15, 0, r0, c7, c10, 4\n"
463	    : : : "r0", "memory"
464	  );
465	
466	  f1c100s_lcd_gpio_init();
467	  f1c100s_tcon_init(&g_lcd_config);
468	  f1c100s_debe_init(&g_lcd_config, priv->fbmem);
469	  putreg32(0x80000000, F1C100S_TCON_BASE + TCON_CTRL);
470	
471	  syslog(LOG_INFO, "RGB LCD %dx%d pll=0x%08x dclkdiv=%u\n",
472	         CONFIG_F1C100S_FB_WIDTH, CONFIG_F1C100S_FB_HEIGHT,
473	         (unsigned)g_lcd_config.pll, g_lcd_config.clkdiv);
474	
475	  /* Setup vtable */
476	
477	  priv->vtable.getvideoinfo = f1c100s_getvideoinfo;
478	  priv->vtable.getplaneinfo = f1c100s_getplaneinfo;
479	#ifdef CONFIG_FB_UPDATE
480	  priv->vtable.updatearea   = f1c100s_updatearea;
481	#endif
482	
483	  /* Register the framebuffer device */
484	
485	  ret = fb_register_device(display, 0, &priv->vtable);
486	  if (ret < 0)
487	    {
488	      gerr("ERROR: fb_register() failed: %d\n", ret);
489	      kmm_free(priv->fbmem);
490	      return ret;
491	    }
492	
493	  ginfo("F1C100s framebuffer initialized successfully\n");
494	  return OK;
495	}
