/*
 * A SPI-NAND factory bad-block marker is a non-0xFF byte at the start of the OOB
 * (column = page_size) of the first page of the block. Load that page and read it.
 */
static int spi_nand_block_is_bad(sunxi_spi_t *spi, uint32_t block_addr)
{
	uint8_t tx[4];
	uint8_t marker = 0xff;

	warning("spi_nand_block_is_bad: addr=0x%lx\r\n", (unsigned long)block_addr);
	spi_nand_load_page(spi, block_addr); /* page 0 of the block */

	tx[0] = OPCODE_READ;					 /* read-from-cache, single IO */
	tx[1] = (uint8_t)(spi->info.page_size >> 8);
	tx[2] = (uint8_t)(spi->info.page_size >> 0);
	tx[3] = 0x0;							 /* dummy */
	spi_transfer(spi, SPI_IO_SINGLE, tx, 4, &marker, 1);

	return marker != 0xff;
}

uint32_t spi_nand_read(sunxi_spi_t *spi, uint8_t *buf, uint32_t addr, uint32_t rxlen)
{
	uint32_t address = addr;
	uint32_t cnt	 = rxlen;
	uint32_t n;
	uint32_t len = 0;
	uint32_t ca;
	uint32_t txlen = 4;
	uint8_t	 tx[6];

	int read_opcode = OPCODE_READ;
	switch (spi->info.mode) {
		case SPI_IO_SINGLE:
			read_opcode = OPCODE_READ;
			break;
		case SPI_IO_DUAL_RX:
			read_opcode = OPCODE_FAST_READ_DUAL_O;
			break;
		case SPI_IO_QUAD_RX:
			read_opcode = OPCODE_FAST_READ_QUAD_O;
			break;
		case SPI_IO_QUAD_IO:
			read_opcode = OPCODE_FAST_READ_QUAD_IO;
			txlen		= 5; // Quad IO has 2 dummy bytes
			break;

		default:
			error("spi_nand: invalid mode\r\n");
			return -1;
	};

	if (addr % spi->info.page_size) {
		error("spi_nand: address is not page-aligned\r\n");
		return -1;
	}

	if (spi->info.id.mfr == SPI_NAND_MFR_GIGADEVICE ||
		spi->info.id.mfr == SPI_NAND_MFR_ESMT) {
		/* Standard SPI-NAND: load each page then read from cache with a
		 * column address. The single-shot else-branch below only works for
		 * Winbond continuous mode, so multi-page reads must loop per page. */
		uint32_t block_size = spi->info.page_size * spi->info.pages_per_block;
		while (cnt > 0) {
			/* At each block boundary, skip factory-marked bad blocks so a bad
			 * block inside the kernel/dtb region doesn't shift the data. */
			if ((address % block_size) == 0) {
				while (spi_nand_block_is_bad(spi, address)) {
					warning("spi_nand: skipping bad block @0x%" PRIx32 "\r\n", address);
					address += block_size;
				}
			}

			ca = address & (spi->info.page_size - 1);
			n  = cnt > (spi->info.page_size - ca) ? (spi->info.page_size - ca) : cnt;

			warning("spi_nand_read: load_page addr=0x%lx ca=0x%lx n=0x%lx cnt=0x%lx\r\n",
				(unsigned long)address, (unsigned long)ca,
				(unsigned long)n, (unsigned long)cnt);
			spi_nand_load_page(spi, address);

			tx[0] = read_opcode;
			tx[1] = (uint8_t)(ca >> 8);
			tx[2] = (uint8_t)(ca >> 0);
			tx[3] = 0x0;

			spi_transfer(spi, spi->info.mode, tx, 4, buf, n);

			address += n;
			buf += n;
			len += n;
			cnt -= n;
		}
	} else {
		spi_nand_load_page(spi, addr);

		// With Winbond, we use continuous mode which has 1 more dummy
		// This allows us to not load each page
		if (spi->info.id.mfr == SPI_NAND_MFR_WINBOND) {
			txlen++;
		}

		ca = address & (spi->info.page_size - 1);

		tx[0] = read_opcode;
		tx[1] = (uint8_t)(ca >> 8);
		tx[2] = (uint8_t)(ca >> 0);
		tx[3] = 0x0;
		tx[4] = 0x0;

		spi_transfer(spi, spi->info.mode, tx, txlen, buf, rxlen);
	}
	return len;
}

