#define OPCODE_NOR_READ		0x03

#define SPI_NOR_READ_CHUNK 0x1000 /* 4 KB per READ burst */

int spi_nor_read(sunxi_spi_t *spi, uint8_t *buf, uint32_t addr, uint32_t len)
{
	uint8_t	 tx[4];
	uint32_t remaining = len;

	/* Issue the READ (0x03) command per chunk, re-sending the (incrementing)
	 * 3-byte address each time, instead of one giant single-shot burst. This
	 * keeps each SPI burst small and is correct on real silicon (0x03 streams
	 * from the supplied address). A single multi-MB burst is both fragile and
	 * needlessly large. */
	while (remaining > 0) {
		uint32_t n = remaining > SPI_NOR_READ_CHUNK ? SPI_NOR_READ_CHUNK : remaining;

		tx[0] = OPCODE_NOR_READ;
		tx[1] = (addr >> 16) & 0xFF;
		tx[2] = (addr >> 8) & 0xFF;
		tx[3] = addr & 0xFF;

		if (spi_transfer(spi, SPI_IO_SINGLE, tx, 4, buf, n) < 0) {
			error("SPI NOR: read failed at 0x%" PRIx32 "\r\n", addr);
			return -1;
		}

		addr += n;
		buf += n;
		remaining -= n;
	}
	return len;
}

#define SPI_CLK_CTL_CDR1_MASK 0xf /* Clock Divide Rate 1,master mode only : SPI_CLK = AHB_CLK/2^n */
#define SPI_CLK_CTL_CDR1(div) (((div)&SPI_CLK_CTL_CDR1_MASK) << 8)
#define SPI_CLK_CTL_DRS		  (0x1 << 12) /* Divide rate select,default,0:rate 1;1:rate 2 */

#define SPI_MOD_CLK 200000000

static uint32_t spi_set_clk(sunxi_spi_t *spi, u32 spi_clk, u32 mclk, u32 cdr2)
{
	uint32_t reg	 = 0;
	uint32_t div	 = 1;
	uint32_t src_clk = mclk;
	uint32_t freq	 = SPI_MOD_CLK;

	if (spi_clk != SPI_MOD_CLK) {
		/* CDR2 */
		if (cdr2) {
			div = mclk / (spi_clk * 2) - 1;
			reg |= SPI_CLK_CTL_CDR2(div) | SPI_CLK_CTL_DRS;
			trace("SPI: CDR2 - n = %lu\r\n", div);
			freq = mclk / (2 * ((div + 1)));
		} else { /* CDR1 */
			while (src_clk > spi_clk) {
				div++;
				src_clk >>= 1;
			}
			reg |= SPI_CLK_CTL_CDR1(div);
			trace("SPI: CDR1 - n = %lu\r\n", div);
			freq = src_clk;
		}
	}

	trace("SPI: clock div=%" PRIu32 " \r\n", div);
	debug("SPI: set clock asked=%" PRIu32 "MHz actual=%" PRIu32 "MHz mclk=%" PRIu32 "MHz\r\n", spi_clk / 1000000, freq / 1000000, mclk / 1000000);

	write32(spi->base + SPI_CCR, reg);

	return freq;
}

