535	/****************************************************************************
536	 * Name: f1c100s_sdio_interrupt
537	 ****************************************************************************/
538	
539	static int f1c100s_sdio_interrupt(int irq, void *context, void *arg)
540	{
541	  FAR struct f1c100s_sdio_dev_s *priv = (FAR struct f1c100s_sdio_dev_s *)arg;
542	  uint32_t rintsts;
543	  sdio_eventset_t wkupevents = 0;
544	
545	  /* Read interrupt status */
546	  rintsts = SDC_GETREG(priv, SDC_RINT_OFFSET);
547	
548	  /* Command done */
549	  if (rintsts & SDC_INT_CMD_DONE)
550	    {
551	      wkupevents |= SDIOWAIT_CMDDONE;
552	      SDC_PUTREG(priv, SDC_RINT_OFFSET, SDC_INT_CMD_DONE);
553	    }
554	
555	  /* Data transfer done */
556	  if (rintsts & SDC_INT_DATA_OVER)
557	    {
558	      wkupevents |= SDIOWAIT_TRANSFERDONE;
559	      SDC_PUTREG(priv, SDC_RINT_OFFSET, SDC_INT_DATA_OVER);
560	
561	      /* Invalidate cache for receive buffer if DMA was used */
562	      if (priv->rxbuffer)
563	        {
564	          up_invalidate_dcache((uintptr_t)priv->rxbuffer,
565	                               (uintptr_t)priv->rxbuffer + priv->remaining);
566	        }
567	    }
568	
569	  /* Response timeout */
570	  if (rintsts & SDC_INT_RESP_TIMEOUT)
571	    {
572	      wkupevents |= SDIOWAIT_RESPONSEDONE;
573	      SDC_PUTREG(priv, SDC_RINT_OFFSET, SDC_INT_RESP_TIMEOUT);
574	    }
575	
576	  /* Other errors */
577	  if (rintsts & SDC_INT_ERROR_MASK)
578	    {
579	      wkupevents |= SDIOWAIT_ERROR;
580	      SDC_PUTREG(priv, SDC_RINT_OFFSET, rintsts & SDC_INT_ERROR_MASK);
581	    }
582	
583	  /* Wakeup waiting thread if any events occurred */
584	  if (wkupevents != 0)
585	    {
586	      priv->wkupevents |= wkupevents;
587	      nxsem_post(&priv->waitsem);
588	    }
589	
590	  return OK;
591	}
