  uint32_t crc;
  uint32_t copy;
  irqstate_t flags;
  int ret;
  f1c100s_tramp_t tramp;

  syslog(LOG_INFO, "boot: loading AP %u bytes from 0x%x\n",
         (unsigned)kv->ap_size, (unsigned)F1C100S_PART_AP_OFFSET);

  ret = f1c100s_bootkv_flash_read(F1C100S_PART_AP_OFFSET,
                                  staging, kv->ap_size);
  if (ret < 0)
    {
      syslog(LOG_ERR, "boot: AP flash read failed %d\n", ret);
      return ret;
    }

  if (memcmp(staging + 4, "eGON.NTX", 8) != 0)
    {
      syslog(LOG_ERR, "boot: AP missing eGON.NTX magic\n");
      return -ENOEXEC;
    }

  crc = crc32(staging, kv->ap_size);
  if (crc != kv->ap_crc32)
    {
      syslog(LOG_ERR, "boot: AP crc 0x%08x != kv 0x%08x\n",
             (unsigned)crc, (unsigned)kv->ap_crc32);
      f1c100s_boot_status("Update failed, retry");
      return -EILSEQ;
    }

  kv->fail_count++;
  ret = f1c100s_bootkv_write(kv);
  if (ret < 0)
    {
      syslog(LOG_ERR, "boot: fail_count write failed %d\n", ret);
      return ret;
    }

