1429	static void f1c100s_sdio_dmasetup(FAR struct f1c100s_sdio_dev_s *priv,
1430	                                   FAR uint8_t *buffer, size_t nbytes)
1431	{
1432	  FAR struct f1c100s_idmac_desc_s *desc = priv->dmadesc;
1433	  uintptr_t bufaddr = (uintptr_t)buffer;
1434	  size_t remaining = nbytes;
1435	  int i = 0;
1436	
1437	  /* Build descriptor chain */
1438	
1439	  while (remaining > 0 && i < F1C100S_SDIO_NDESC)
1440	    {
1441	      size_t chunk = remaining > IDMAC_MAX_BUFFER ? IDMAC_MAX_BUFFER : remaining;
1442	
1443	      desc[i].des0 = IDMAC_DES0_OWN | IDMAC_DES0_CH | IDMAC_DES0_DIC;
1444	      desc[i].des1 = (chunk == IDMAC_MAX_BUFFER) ? 0 : chunk;
1445	      desc[i].des2 = bufaddr;
1446	      desc[i].des3 = (uintptr_t)&desc[i + 1];
1447	
1448	      /* Mark first descriptor */
1449	
1450	      if (i == 0)
1451	        {
1452	          desc[i].des0 |= IDMAC_DES0_FD;
1453	        }
1454	
1455	      bufaddr += chunk;
1456	      remaining -= chunk;
1457	      i++;
1458	    }
1459	
1460	  /* Mark last descriptor */
1461	
1462	  if (i > 0)
1463	    {
1464	      desc[i - 1].des0 |= (IDMAC_DES0_LD | IDMAC_DES0_ER);
1465	      desc[i - 1].des0 &= ~IDMAC_DES0_DIC;
1466	      desc[i - 1].des3 = 0;  /* End of chain */
1467	    }
1468	
1469	  /* Flush cache for descriptors */
1470	
1471	  up_clean_dcache((uintptr_t)desc,
1472	                  (uintptr_t)desc + i * sizeof(struct f1c100s_idmac_desc_s));
1473	
1474	  /* Flush cache for buffer (write) or invalidate (read) done in caller */
1475	}
