/****************************************************************************
 * Name: f1c100s_sdio_dma_arm
 *
 * Description:
 *   Arm the IDMAC engine in the order T113's known-working golden HAL
 *   uses: DMA-access mode, GCTRL DMA_EN + FIFO/DMA reset (wait
 *   self-clear), IDMAC soft reset (wait self-clear), clear stale IDST,
 *   fixed-burst + IDMAC enable, IDMAC interrupt enable, descriptor list
 *   base, FIFO/burst watermark.
 *
 *   Previous code wrote IDMAC_DMAC_SWR and immediately overwrote the
 *   same register with FB|IDMAC_EN|PBL_8 with no wait -- the reset
 *   pulse was never given time to take effect. It also never reset
 *   GCTRL's FIFO/DMA state per-transfer (only once at hwreset()) and
 *   never enabled IDST/IDIE. Confirmed on real hardware: CMD17 failed
 *   with rintsts showing SDC_INT_FIFO_RUN_ERR -- nothing was actually
 *   draining the FIFO into DRAM.
 *
 ****************************************************************************/

static void f1c100s_sdio_dma_arm(FAR struct f1c100s_sdio_dev_s *priv,
                                  uint32_t idie)
{
  uint32_t regval;
  int t;

  /* FIFO accessed by internal DMA (clear AHB-access bit), then DMA
   * enable + FIFO/DMA reset; wait for the resets to self-clear.
   */

  regval = SDC_GETREG(priv, SDC_GCTRL_OFFSET);
  regval &= ~SDC_GCTRL_ACCESS_BY_AHB;
  regval |= SDC_GCTRL_DMA_EN | SDC_GCTRL_FIFO_RST | SDC_GCTRL_DMA_RST;
  SDC_PUTREG(priv, SDC_GCTRL_OFFSET, regval);
  for (t = 10000; t > 0 &&
       (SDC_GETREG(priv, SDC_GCTRL_OFFSET) &
        (SDC_GCTRL_FIFO_RST | SDC_GCTRL_DMA_RST)) != 0; t--)
    {
    }

  /* IDMAC soft reset; wait self-clear. */

  IDMAC_PUTREG(priv, F1C100S_IDMAC_DMAC_OFFSET, IDMAC_DMAC_SWR);
  for (t = 10000; t > 0 &&
